  ('ee0479e0-ca45-5ce9-ba53-21c76653678a', 'Biology', 'Cell Structure', 'Which organelle is the primary site of ATP (energy) production in the cell?', 'Mitochondria', 'Golgi apparatus', 'Ribosome', 'Lysosome', 'A', 'Mitochondria are called the powerhouse of the cell because they carry out cellular respiration and generate most of the cell''s ATP.', 'easy'),
  ('f7f9cb5e-f1ec-5e84-98ba-c797da5e8d8c', 'Biology', 'Cell Structure', 'Which of the following structures is found ONLY in plant cells, not in animal cells?', 'Mitochondria', 'Nucleus', 'Chloroplast', 'Ribosome', 'C', 'Chloroplasts contain chlorophyll and carry out photosynthesis; they are present only in plant cells and some protists, not in animal cells.', 'easy'),
  ('4038ede2-f423-54a3-a94b-e506fbe07c8b', 'Biology', 'Cell Structure', 'The fluid mosaic model describes the structure of the:', 'Nucleolus', 'Mitochondrial matrix', 'Cell wall', 'Plasma membrane', 'D', 'The fluid mosaic model (Singer & Nicolson, 1972) describes the plasma membrane as a fluid phospholipid bilayer with embedded proteins.', 'medium'),
  ('017dc3f0-a00c-5e44-a923-c5b722bdadf6', 'Biology', 'Cell Structure', 'Ribosomes are the site of:', 'Lipid storage', 'Cellular respiration', 'Protein synthesis', 'Photosynthesis', 'C', 'Ribosomes read mRNA codons and assemble amino acids into proteins (translation).', 'easy'),
  ('87c06efc-12b5-5354-bfc6-0530498bf6d3', 'Biology', 'Cell Structure', 'Which organelle modifies, packages and sorts proteins for secretion?', 'Endoplasmic reticulum', 'Peroxisome', 'Vacuole', 'Golgi apparatus', 'D', 'The Golgi apparatus modifies, packages and sorts proteins and lipids, then ships them to their destinations in vesicles.', 'medium'),
  ('eab09e24-c617-509b-acbd-dcb9e83b6b54', 'Biology', 'Cell Structure', 'The semifluid material inside the cell that holds the organelles is called the:', 'Cell wall', 'Nucleus', 'Matrix', 'Cytoplasm', 'D', 'The cytoplasm is everything inside the cell membrane outside the nucleus; the organelles are suspended in it.', 'medium'),
  ('0211de42-4e2c-5bd0-9407-0afce02dd50c', 'Biology', 'Cell Structure', 'Which of the following is a double membrane-bound organelle containing its own DNA?', 'Lysosome', 'Centriole', 'Mitochondria', 'Ribosome', 'C', 'Mitochondria (and chloroplasts) are double-membrane organelles with their own circular DNA and ribosomes — evidence for the endosymbiotic theory.', 'hard'),
  ('db34592e-fb38-5e5d-9206-0e59d2d7d256', 'Biology', 'Cell Structure', 'Which cell structure controls what enters and leaves the cell?', 'Vacuole', 'Plasma membrane', 'Cell wall', 'Nucleus', 'B', 'The plasma membrane is selectively permeable and regulates the passage of substances in and out of the cell.', 'easy'),
  ('14e701d1-8ea2-5a0d-b90c-53bb6772b820', 'Biology', 'Cell Structure', 'Bacterial cells are classified as prokaryotic because they:', 'Contain chloroplasts', 'Lack a membrane-bound nucleus', 'Have mitochondria', 'Have a true nucleus', 'B', 'Prokaryotes lack a membrane-bound nucleus; their genetic material lies freely in the cytoplasm. Bacteria are prokaryotes.', 'easy'),
  ('b90995dd-de39-5959-abd2-bba134d4b0eb', 'Biology', 'Cell Structure', 'Rough endoplasmic reticulum and the Golgi apparatus work together in:', 'Protein synthesis and packaging', 'Photosynthesis', 'Energy release only', 'DNA replication', 'A', 'Proteins made at the rough ER travel in vesicles to the Golgi apparatus, which packages and exports them.', 'medium'),
  ('23d26b1c-47ec-58c0-b7fe-330de6e3f46d', 'Biology', 'Biological Molecules', 'Which monosaccharide is the main energy source carried in blood?', 'Ribose', 'Glucose', 'Fructose', 'Galactose', 'B', 'Glucose (C6H12O6) is the primary fuel for cellular respiration and the sugar transported in the blood of most animals.', 'easy'),
  ('b1cf434b-8185-5906-b169-6fe950ecf372', 'Biology', 'Biological Molecules', 'Starch, glycogen and cellulose are all:', 'Lipids', 'Polysaccharides', 'Proteins', 'Nucleic acids', 'B', 'They are polysaccharides — polymers of monosaccharides. Starch (plant energy storage), glycogen (animal energy storage) and cellulose (plant cell walls).', 'easy'),
  ('a3b65b04-5aa5-51c6-b105-a70ed594c450', 'Biology', 'Biological Molecules', 'The monomer (building block) of proteins is the:', 'Amino acid', 'Monosaccharide', 'Nucleotide', 'Fatty acid', 'A', 'Proteins are polymers of amino acids joined by peptide bonds.', 'easy'),
  ('d1749440-f660-5fdb-a6cd-bf27dc19d0fb', 'Biology', 'Biological Molecules', 'The bond that links amino acids together in a protein is a:', 'Glycosidic bond', 'Peptide bond', 'Phosphodiester bond', 'Hydrogen bond', 'B', 'A peptide bond is the covalent linkage between the carboxyl group of one amino acid and the amino group of the next.', 'easy'),
  ('465deba5-6fe3-5a95-a66c-25c9574120bf', 'Biology', 'Biological Molecules', 'Which of the following is NOT a lipid?', 'Triglyceride', 'Cellulose', 'Cholesterol', 'Phospholipid', 'B', 'Cellulose is a polysaccharide (carbohydrate). Triglycerides, phospholipids and cholesterol are all lipids.', 'medium'),
  ('ec854186-2e1e-5f74-9e4f-4202d126dba0', 'Biology', 'Biological Molecules', 'DNA and RNA are classified as:', 'Carbohydrates', 'Proteins', 'Nucleic acids', 'Lipids', 'C', 'Nucleic acids (DNA and RNA) are polymers of nucleotides and store and transmit genetic information.', 'easy'),
  ('e61cf9ee-d474-5926-a54d-b22fd4b1db4f', 'Biology', 'Biological Molecules', 'The double helix structure of DNA was described by:', 'Mendel and Morgan', 'Watson and Crick', 'Lamarck and Darwin', 'Pasteur and Koch', 'B', 'James Watson and Francis Crick proposed the double-helix model of DNA in 1953.', 'easy'),
  ('d9a0092e-65c7-5bdf-8c0e-e1e8bcca72b3', 'Biology', 'Biological Molecules', 'The biological catalysts that speed up reactions in the body are:', 'Enzymes', 'Vitamins', 'Hormones', 'Minerals', 'A', 'Enzymes are usually proteins that act as biological catalysts, dramatically speeding up biochemical reactions.', 'easy'),
  ('b9547dfc-6ced-556b-9295-7661586a6c36', 'Biology', 'Biological Molecules', 'An enzyme that has lost its shape and activity due to high temperature is said to be:', 'Polymerised', 'Hydrolysed', 'Denatured', 'Saturated', 'C', 'Excess heat breaks the weak bonds holding an enzyme''s 3D shape, denaturing it and destroying its activity (usually irreversibly).', 'medium'),
  ('05a9e0db-7464-5156-acbc-c1cd9f51c025', 'Biology', 'Biological Molecules', 'The optimum temperature for most human enzymes is about:', '25°C', '0°C', '37°C', '60°C', 'C', 'Most human enzymes work best near normal body temperature, about 37°C.', 'easy'),
  ('a46f3eeb-3b08-5147-8293-908439dfd6df', 'Biology', 'Bioenergetics', 'Photosynthesis takes place in which organelle?', 'Ribosome', 'Chloroplast', 'Mitochondria', 'Nucleus', 'B', 'Chloroplasts contain chlorophyll, which captures light energy used to synthesise glucose from CO2 and water.', 'easy'),
  ('c65ceb25-7ce4-5ec1-a694-6d1cd522c58f', 'Biology', 'Bioenergetics', 'The net balanced equation for photosynthesis is:', '6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂', 'CO₂ + H₂O → C₆H₁₂O₆', 'C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O', 'O₂ + H₂O → CO₂ + glucose', 'A', 'Photosynthesis: carbon dioxide + water + light energy → glucose + oxygen.', 'medium'),
  ('3a0f0834-7d18-5ae9-8ba3-b838ca6a2946', 'Biology', 'Bioenergetics', 'Aerobic respiration releases energy from glucose in the presence of oxygen to form:', 'CO₂ and H₂O', 'Only ethanol', 'Nitrogen', 'Only lactic acid', 'A', 'Aerobic respiration: glucose + oxygen → CO₂ + H₂O + energy (ATP).', 'easy'),
  ('c45a1f59-7c4b-5495-a6f7-924871fe1e86', 'Biology', 'Bioenergetics', 'When oxygen is in short supply, muscle cells produce ATP through:', 'Photosynthesis', 'Anaerobic respiration (fermentation)', 'Electron transport only', 'The Krebs cycle only', 'B', 'In anaerobic conditions, muscle cells ferment glucose to lactic acid, producing a small amount of ATP without oxygen.', 'medium'),
  ('9a371a93-30d6-5d15-8ccf-3407379b08f2', 'Biology', 'Bioenergetics', 'Glycolysis, the first stage of respiration, occurs in the:', 'Chloroplast', 'Nucleus', 'Mitochondria', 'Cytoplasm', 'D', 'Glycolysis takes place in the cytoplasm and does not require oxygen.', 'medium'),
  ('32a97a4c-f673-5a83-b02a-1b26bd1430b7', 'Biology', 'Bioenergetics', 'The Krebs cycle and electron transport chain both take place in the:', 'Cell membrane', 'Mitochondria', 'Cytoplasm', 'Ribosomes', 'B', 'The Krebs cycle runs in the mitochondrial matrix and the electron transport chain on the inner mitochondrial membrane.', 'medium'),
  ('caf64c9b-5cfd-5216-ac72-96f4c39ea50c', 'Biology', 'Coordination and Control', 'The "master gland" of the endocrine system that controls many other glands is the:', 'Adrenal', 'Pituitary', 'Thyroid', 'Pancreas', 'B', 'The pituitary gland secretes hormones (TSH, ACTH, FSH, LH, GH) that regulate other endocrine glands.', 'easy'),
  ('ab31b2da-da8e-59d1-91a7-0e14d375db2d', 'Biology', 'Coordination and Control', 'The hormone that lowers blood glucose by promoting glucose uptake into cells is:', 'Glucagon', 'Insulin', 'Thyroxine', 'Adrenaline', 'B', 'Insulin, released by the beta cells of the pancreas, lowers blood glucose. Glucagon raises it.', 'medium'),
  ('9562bee2-fa87-5225-b5c8-1a0c16e5e3eb', 'Biology', 'Coordination and Control', 'The basic unit of the nervous system is the:', 'Neuron', 'Axon', 'Nephron', 'Synapse', 'A', 'The neuron is the nerve cell — the functional unit that transmits nerve impulses.', 'easy'),
  ('fe5a8fa2-1c3b-5b8c-bc4f-23528f973ea7', 'Biology', 'Coordination and Control', 'The junction where an impulse passes from one neuron to the next is called a:', 'Node', 'Synapse', 'Dendrite', 'Ganglion', 'B', 'A synapse is the gap between neurons across which neurotransmitter chemicals carry the impulse.', 'easy'),
  ('05d27753-5d51-50e4-9f24-f8654d6089a2', 'Biology', 'Coordination and Control', 'Adrenaline, which prepares the body for fight-or-flight, is secreted by the:', 'Parathyroid', 'Adrenal medulla', 'Pancreas', 'Pituitary', 'B', 'The adrenal medulla secretes adrenaline (epinephrine), which prepares the body for “fight or flight.”', 'medium'),
  ('078a1be0-15ac-56be-863e-1d1aefec8eff', 'Biology', 'Coordination and Control', 'Which part of the brain controls balance and coordination of movement?', 'Hypothalamus', 'Medulla oblongata', 'Cerebellum', 'Cerebrum', 'C', 'The cerebellum coordinates voluntary movements and maintains balance and posture.', 'medium'),
  ('a74ae76e-97e3-557e-a971-a1bfbb61fd39', 'Biology', 'Homeostasis', 'The functional unit of the kidney is the:', 'Neuron', 'Bowman''s capsule only', 'Alveolus', 'Nephron', 'D', 'The nephron is the microscopic filtering unit of the kidney where blood is filtered and urine is formed.', 'easy'),
  ('8f58c6a3-b909-5ae6-a388-ec81ca1f6346', 'Biology', 'Homeostasis', 'If the body has too much water, the kidney produces:', 'More glucose', 'Concentrated urine', 'Dilute urine', 'No urine at all', 'C', 'When water intake is high, antidiuretic hormone (ADH) release drops and the kidney excretes more dilute urine.', 'medium'),
  ('0d0bfb20-7dcc-5d05-b8ff-ded685248b4b', 'Biology', 'Homeostasis', 'Normal human body temperature is maintained at approximately:', '40°C', '32°C', '37°C', '42°C', 'C', 'The hypothalamus regulates body temperature around a set point of about 37°C (98.6°F).', 'easy'),
  ('f2ae50b8-eeb1-5c0b-ab01-3e37badc595b', 'Biology', 'Homeostasis', 'The maintenance of a constant internal environment despite external changes is called:', 'Digestion', 'Homeostasis', 'Metabolism', 'Osmosis', 'B', 'Homeostasis is the maintenance of a stable internal environment in the face of external change.', 'easy'),
  ('b4e20efa-f2e3-553f-a2c4-41a0156ff894', 'Biology', 'Support and Movement', 'In an antagonistic pair of muscles, when one contracts the other:', 'Also contracts', 'Splits', 'Relaxes', 'Atrophies', 'C', 'Antagonistic muscles (e.g. biceps and triceps) work as opposite pairs — one contracts while the other relaxes.', 'medium'),
  ('c12043d0-24b8-59cf-b39f-fc5fc03e201b', 'Biology', 'Support and Movement', 'The contractile protein in muscles that interacts with myosin to cause contraction is:', 'Keratin', 'Hemoglobin', 'Collagen', 'Actin', 'D', 'Actin (thin filaments) interacts with myosin (thick filaments) to produce muscle contraction.', 'medium'),
  ('8b6505ec-df21-5751-9d73-3e7777ead226', 'Biology', 'Genetics', 'The basic unit of heredity passed from parent to offspring is the:', 'Trait', 'Cytoplasm', 'Gene', 'Chromosome pair', 'C', 'A gene is a segment of DNA that codes for a protein or trait and is the unit of heredity.', 'easy'),
  ('cd08c063-8e05-5e06-b119-153d9cfd4a40', 'Biology', 'Genetics', 'A normal human somatic (body) cell contains how many chromosomes?', '23', '46', '48', '44', 'B', 'Human somatic cells are diploid (2n) with 46 chromosomes (23 pairs); gametes have 23.', 'easy'),
  ('b7abedd1-0a20-5202-b2ce-30477828af37', 'Biology', 'Genetics', 'The cell division that produces four genetically different haploid gametes is:', 'Meiosis', 'Binary fission', 'Mitosis', 'Budding', 'A', 'Meiosis produces four genetically distinct haploid gametes; mitosis produces two identical diploid cells.', 'medium'),
  ('2074f521-03ff-5f85-8ae7-1b511b287129', 'Biology', 'Genetics', 'A healthy human female has which sex chromosomes?', 'YY', 'XO', 'XY', 'XX', 'D', 'Females carry two X chromosomes (XX); males carry one X and one Y (XY).', 'easy'),
  ('7dbdb2d2-8295-5999-9ba8-a5b04615bb80', 'Biology', 'Genetics', 'Which molecule carries the genetic code from DNA in the nucleus to the ribosomes?', 'Lipid', 'mRNA', 'ATP', 'Protein', 'B', 'Messenger RNA (mRNA) carries the genetic code from DNA to the ribosome for translation.', 'easy'),
  ('af696b8c-7345-5ea0-a908-32c8cbb3f48e', 'Biology', 'Reproduction', 'In humans, the female gamete is the:', 'Zygote', 'Ovum (egg)', 'Embryo', 'Sperm', 'B', 'The ovum (egg) is the female gamete; the sperm is the male gamete; their fusion forms a zygote.', 'easy'),
  ('b75a24e3-eadc-5bf1-a182-7e916149af7e', 'Biology', 'Reproduction', 'The fusion of a sperm with an ovum to form a zygote is called:', 'Menstruation', 'Fertilisation', 'Ovulation', 'Implantation', 'B', 'Fertilisation is the union of the sperm and egg to form a diploid zygote.', 'easy'),
  ('8a784764-e10a-5d75-a7e4-4fd4da4716ec', 'Biology', 'Reproduction', 'Asexual reproduction differs from sexual reproduction because asexual reproduction:', 'Always produces gametes', 'Involves two parents', 'Involves one parent and produces genetically identical offspring', 'Requires fertilisation', 'C', 'Asexual reproduction (binary fission, budding) involves a single parent and produces genetically identical (clonal) offspring.', 'medium'),
  ('48fdf7ed-b9f3-533e-abea-7ba3d5e5f3a0', 'Biology', 'Ecology', 'The study of interactions between organisms and their environment is:', 'Genetics', 'Embryology', 'Histology', 'Ecology', 'D', 'Ecology is the scientific study of how organisms interact with one another and with their environment.', 'easy'),
  ('feb580a4-6a8c-5a4a-bb2e-d999d3ae86be', 'Biology', 'Ecology', 'Organisms that make their own food by photosynthesis are called:', 'Consumers', 'Herbivores', 'Producers (autotrophs)', 'Decomposers', 'C', 'Producers (autotrophs), mainly green plants, make their own food and form the base of food chains.', 'easy'),
  ('e3a61e46-6dc6-5e62-b6a1-ab2c16e6b047', 'Biology', 'Ecology', 'An organism that breaks down dead organic matter and recycles nutrients is a:', 'Primary consumer', 'Producer', 'Predator', 'Decomposer', 'D', 'Decomposers (bacteria and fungi) break down dead material and recycle nutrients back into the ecosystem.', 'easy'),
  ('28ae0572-f80a-57cb-8539-97e4a66e6800', 'Biology', 'Ecology', 'Which food chain is correctly ordered?', 'Grass → Grasshopper → Frog → Snake', 'Grasshopper → Grass → Frog → Snake', 'Grass → Frog → Grasshopper → Snake', 'Snake → Frog → Grasshopper → Grass', 'A', 'Energy flows from producer (grass) to primary consumer (grasshopper) to secondary consumer (frog) to tertiary consumer (snake).', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-111111111101', 'Biology', 'Cell Structure', 'Which of the following structures is responsible for intracellular digestion and recycling of worn-out organelles?', 'Peroxisome', 'Lysosome', 'Centriole', 'Smooth ER', 'B', 'Lysosomes contain hydrolytic enzymes that break down macromolecules, damaged organelles and foreign material inside the cell.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-111111111102', 'Biology', 'Cell Structure', 'The endoplasmic reticulum that lacks ribosomes on its surface is called:', 'Rough ER', 'Smooth ER', 'Golgi apparatus', 'Nuclear envelope', 'B', 'Smooth endoplasmic reticulum lacks ribosomes and is primarily involved in lipid synthesis, detoxification and calcium storage.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-111111111103', 'Biology', 'Cell Structure', 'Which of the following is a feature unique to animal cells but absent in plant cells?', 'Cell wall', 'Chloroplast', 'Centrioles', 'Large central vacuole', 'C', 'Centrioles are present in animal cells and play a key role in spindle formation during cell division. Most plant cells lack centrioles.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-111111111104', 'Biology', 'Cell Structure', 'The nucleus is surrounded by a double membrane called the:', 'Cell membrane', 'Plasma lemma', 'Nuclear envelope', 'Golgi membrane', 'C', 'The nuclear envelope is a double membrane with nuclear pores that regulate the passage of RNA and proteins between the nucleus and cytoplasm.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-111111111105', 'Biology', 'Cell Structure', 'In which part of a prokaryotic cell is the DNA found?', 'In a membrane-bound nucleus', 'In the nucleoid region', 'Inside mitochondria', 'Attached to histone proteins in a true nucleus', 'B', 'Prokaryotes lack a membrane-bound nucleus. Their DNA is concentrated in an irregular region of the cytoplasm called the nucleoid.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-111111111106', 'Biology', 'Cell Structure', 'Plasmolysis in plant cells occurs when:', 'The cell absorbs excess water', 'The cell is placed in a hypertonic solution', 'The cell wall dissolves', 'Chloroplasts are removed', 'B', 'In a hypertonic solution water leaves the cell by osmosis, causing the cytoplasm to shrink and pull away from the cell wall — this is plasmolysis.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-111111111107', 'Biology', 'Cell Structure', 'The process by which cells engulf large particles or droplets by wrapping them in membrane is called:', 'Exocytosis', 'Osmosis', 'Phagocytosis', 'Diffusion', 'C', 'Phagocytosis ("cell eating") is a form of endocytosis in which the cell membrane surrounds and engulfs large particles.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-222222222201', 'Biology', 'Biological Molecules', 'Which of the following is a disaccharide?', 'Glucose', 'Maltose', 'Glycogen', 'Cellulose', 'B', 'Maltose is a disaccharide made of two glucose units. Glucose is a monosaccharide; glycogen and cellulose are polysaccharides.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-222222222202', 'Biology', 'Biological Molecules', 'Nucleotides are the building blocks of:', 'Lipids', 'Proteins', 'Polysaccharides', 'Nucleic acids', 'D', 'Each nucleotide consists of a nitrogenous base, a pentose sugar and a phosphate group. Nucleotides polymerise to form DNA and RNA.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-222222222203', 'Biology', 'Biological Molecules', 'Which level of protein structure refers to the overall three-dimensional shape of a single polypeptide chain?', 'Primary structure', 'Secondary structure', 'Tertiary structure', 'Quaternary structure', 'C', 'The tertiary structure is the 3D folding of a single polypeptide chain, stabilised by disulfide bridges, hydrogen bonds and ionic bonds.', 'hard'),
  ('a1b2c3d4-e5f6-7890-abcd-222222222204', 'Biology', 'Biological Molecules', 'Fats and oils differ mainly in that fats are:', 'Unsaturated at higher temperature', 'Solid at room temperature due to saturated fatty acid chains', 'Made of nucleotides', 'Water-soluble', 'B', 'Fats (e.g. butter) contain more saturated fatty acids and are solid at room temperature; oils (e.g. olive oil) contain more unsaturated fatty acids and are liquid.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-222222222205', 'Biology', 'Biological Molecules', 'The bond that joins two monosaccharides to form a disaccharide is a:', 'Peptide bond', 'Phosphodiester bond', 'Glycosidic bond', 'Ionic bond', 'C', 'A glycosidic bond forms between monosaccharides by a condensation reaction, releasing a water molecule.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-222222222206', 'Biology', 'Biological Molecules', 'Which statement about enzymes is correct?', 'They are permanently changed during a reaction', 'They increase the activation energy of reactions', 'They lower the activation energy of reactions', 'They are consumed by the reaction', 'C', 'Enzymes catalyse reactions by lowering the activation energy, not by being consumed or permanently changed.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-222222222207', 'Biology', 'Biological Molecules', 'The nitrogenous base found in RNA but NOT in DNA is:', 'Adenine', 'Guanine', 'Uracil', 'Cytosine', 'C', 'RNA contains uracil (U) instead of thymine (T). Adenine, guanine and cytosine are found in both DNA and RNA.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-333333333301', 'Biology', 'Bioenergetics', 'During the light-dependent reactions of photosynthesis, water molecules are split to release:', 'Carbon dioxide and glucose', 'Oxygen and hydrogen ions (protons)', 'ATP and carbon dioxide', 'Starch and oxygen', 'B', 'Photolysis of water in the light-dependent reactions produces oxygen gas (released as a by-product), hydrogen ions and electrons.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-333333333302', 'Biology', 'Bioenergetics', 'The final electron acceptor in the electron transport chain during aerobic respiration is:', 'NAD⁺', 'FAD', 'Carbon dioxide', 'Oxygen', 'D', 'Oxygen accepts electrons at the end of the electron transport chain and combines with hydrogen to form water.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-333333333303', 'Biology', 'Bioenergetics', 'In yeast, anaerobic respiration (fermentation) produces:', 'Lactic acid', 'Ethanol and carbon dioxide', 'Glucose and oxygen', 'Acetic acid and hydrogen', 'B', 'Yeast carries out alcoholic fermentation: glucose → ethanol + CO₂ + small amount of ATP.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-333333333304', 'Biology', 'Bioenergetics', 'Which pigment absorbs light primarily in the red and blue wavelengths for photosynthesis?', 'Carotene', 'Xanthophyll', 'Chlorophyll a', 'Phycocyanin', 'C', 'Chlorophyll a is the main photosynthetic pigment and absorbs light most strongly in the red and blue regions of the spectrum.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-333333333305', 'Biology', 'Bioenergetics', 'The net ATP yield from glycolysis per molecule of glucose is:', '36 ATP', '2 ATP', '38 ATP', '4 ATP', 'B', 'Glycolysis produces 4 ATP but consumes 2, giving a net yield of 2 ATP per glucose molecule.', 'hard'),
  ('a1b2c3d4-e5f6-7890-abcd-333333333306', 'Biology', 'Bioenergetics', 'The Calvin cycle of photosynthesis takes place in the:', 'Thylakoid membrane', 'Inner mitochondrial membrane', 'Stroma of the chloroplast', 'Cytoplasm', 'C', 'The Calvin cycle (light-independent reactions) occurs in the stroma of the chloroplast, fixing CO₂ into glucose.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-333333333307', 'Biology', 'Bioenergetics', 'Which of the following is an energy carrier molecule produced during the Krebs cycle?', 'mRNA', 'NADH', 'DNA polymerase', 'Glycogen', 'B', 'NADH is a reduced coenzyme produced during the Krebs cycle and carries high-energy electrons to the electron transport chain.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-444444444401', 'Biology', 'Coordination and Control', 'The hormone thyroxine is produced by the:', 'Adrenal gland', 'Thyroid gland', 'Pancreas', 'Ovary', 'B', 'Thyroxine (T4) is produced by the thyroid gland and regulates metabolic rate, growth and development.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-444444444402', 'Biology', 'Coordination and Control', 'The region of the brain responsible for higher mental functions such as reasoning, memory and speech is the:', 'Cerebellum', 'Medulla oblongata', 'Hypothalamus', 'Cerebrum', 'D', 'The cerebrum is the largest part of the brain and controls higher-order functions including thought, memory, language and voluntary movement.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-444444444403', 'Biology', 'Coordination and Control', 'A reflex arc bypasses the brain so that the response is:', 'Voluntary and slow', 'Involuntary and rapid', 'Controlled by the cerebrum', 'Delayed by conscious thought', 'B', 'A reflex arc sends the nerve impulse directly from a sensory receptor to the spinal cord and back to a muscle, producing an immediate, involuntary response.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-444444444404', 'Biology', 'Coordination and Control', 'Which gland is controlled by the hypothalamus through releasing and inhibiting hormones?', 'Thyroid', 'Adrenal cortex', 'Pituitary gland', 'Pancreas', 'C', 'The hypothalamus regulates the anterior pituitary by secreting releasing and inhibiting hormones that control pituitary hormone secretion.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-444444444405', 'Biology', 'Coordination and Control', 'The neurotransmitter released at the neuromuscular junction to stimulate muscle contraction is:', 'Dopamine', 'Adrenaline', 'Acetylcholine', 'Serotonin', 'C', 'Acetylcholine (ACh) is the neurotransmitter released at the neuromuscular junction, binding to receptors on the muscle fibre to trigger contraction.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-444444444406', 'Biology', 'Coordination and Control', 'Negative feedback in the endocrine system works to:', 'Amplify a hormonal response indefinitely', 'Return hormone levels back to a normal range', 'Stop all hormone secretion permanently', 'Increase hormone levels without limit', 'B', 'Negative feedback detects when a hormone level is too high or too low and triggers mechanisms to restore it to the set point.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-555555555501', 'Biology', 'Homeostasis', 'Antidiuretic hormone (ADH) acts on the:', 'Liver', 'Distal convoluted tubule and collecting duct of the kidney', 'Stomach lining', 'Lung alveoli', 'B', 'ADH increases the permeability of the distal convoluted tubule and collecting duct to water, promoting water reabsorption.', 'hard'),
  ('a1b2c3d4-e5f6-7890-abcd-555555555502', 'Biology', 'Homeostasis', 'When body temperature rises, the thermoregulatory centre in the hypothalamus triggers:', 'Shivering and vasoconstriction', 'Vasodilation of skin capillaries and sweating', 'Increased metabolic rate', 'Constriction of sweat glands', 'B', 'The hypothalamus causes blood vessels near the skin to dilate (vasodilation) and stimulates sweat glands to release sweat, both of which help cool the body.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-555555555503', 'Biology', 'Homeostasis', 'In the kidney, the process of reabsorption of glucose occurs mainly in the:', 'Bowman''s capsule', 'Loop of Henle', 'Proximal convoluted tubule', 'Collecting duct', 'C', 'Nearly all glucose is reabsorbed from the filtrate in the proximal convoluted tubule by active transport under normal conditions.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-555555555504', 'Biology', 'Homeostasis', 'Sweating helps the body cool down because:', 'Sweat absorbs heat from the blood', 'Evaporation of sweat from the skin surface absorbs heat energy', 'Sweat contains enzymes that generate cold', 'Sweat insulates the body from external heat', 'B', 'When sweat evaporates from the skin it absorbs latent heat of vaporisation from the body, cooling the skin surface and the blood beneath.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-555555555505', 'Biology', 'Homeostasis', 'A person with diabetes mellitus may have glucose in their urine because:', 'The liver cannot produce any glucose', 'Blood glucose exceeds the renal threshold for reabsorption', 'The kidneys produce extra glucose', 'Insulin increases glucose excretion', 'B', 'When blood glucose is very high (as in uncontrolled diabetes), glucose exceeds the kidney''s reabsorption capacity and spills into the urine.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-555555555506', 'Biology', 'Homeostasis', 'The countercurrent mechanism in the loop of Henle helps to:', 'Filter blood', 'Produce concentrated urine by creating a salt gradient in the medulla', 'Reabsorb all glucose', 'Secret urea into the blood', 'B', 'The countercurrent multiplier in the loop of Henle creates an osmotic gradient in the medulla that allows the collecting duct to produce concentrated urine.', 'hard'),
  ('a1b2c3d4-e5f6-7890-abcd-666666666601', 'Biology', 'Genetics', 'In Mendel''s experiments, the allele that is expressed when both dominant and recessive alleles are present is called the:', 'Recessive allele', 'Co-dominant allele', 'Dominant allele', 'Hemizygous allele', 'C', 'A dominant allele masks the effect of a recessive allele in a heterozygous individual and is always expressed in the phenotype.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-666666666602', 'Biology', 'Genetics', 'A cross between a homozygous tall plant (TT) and a homozygous short plant (tt) produces offspring that are all:', 'Short (tt)', 'Heterozygous tall (Tt)', 'Homozygous tall (TT)', 'A 3:1 tall to short ratio', 'B', 'All F₁ offspring receive one dominant allele (T) from one parent and one recessive allele (t) from the other, making them heterozygous (Tt) and phenotypically tall.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-666666666603', 'Biology', 'Genetics', 'Crossing over occurs during which phase of meiosis?', 'Metaphase II', 'Anaphase I', 'Prophase I', 'Telophase II', 'C', 'Crossing over (exchange of segments between non-sister chromatids of homologous chromosomes) occurs during prophase I of meiosis, increasing genetic variation.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-666666666604', 'Biology', 'Genetics', 'Which blood group is considered the universal donor?', 'AB', 'A', 'B', 'O', 'D', 'Blood group O (Rh⁻) lacks A and B antigens on red blood cells, so it can be transfused to recipients of any blood group without causing an immune reaction.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-666666666605', 'Biology', 'Genetics', 'The process by which a segment of DNA is used as a template to make a complementary RNA molecule is called:', 'Translation', 'Replication', 'Transcription', 'Transformation', 'C', 'Transcription is the synthesis of an RNA copy from a DNA template, carried out by RNA polymerase in the nucleus.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-666666666606', 'Biology', 'Genetics', 'Sickle cell anaemia is caused by a mutation in the gene coding for:', 'Insulin', 'Haemoglobin', 'Collagen', 'Myosin', 'B', 'A single nucleotide change in the haemoglobin gene (HBB) substitutes valine for glutamic acid in the β-globin chain, causing sickle-shaped red blood cells.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-666666666607', 'Biology', 'Genetics', 'In a dihybrid cross between two heterozygous parents (RrYy × RrYy), the expected phenotypic ratio in the F₂ generation is:', '1:1', '3:1', '9:3:3:1', '1:2:1', 'C', 'A dihybrid cross of two double heterozygotes yields a 9:3:3:1 ratio — 9 dominant for both traits, 3 dominant for one and recessive for the other, and 1 recessive for both.', 'hard'),
  ('a1b2c3d4-e5f6-7890-abcd-666666666608', 'Biology', 'Genetics', 'Which type of RNA carries amino acids to the ribosome during translation?', 'mRNA', 'rRNA', 'tRNA', 'snRNA', 'C', 'Transfer RNA (tRNA) molecules carry specific amino acids to the ribosome and match their anticodons with complementary mRNA codons.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-777777777701', 'Biology', 'Reproduction', 'The structure in the female reproductive system where the embryo implants during pregnancy is the:', 'Ovary', 'Fallopian tube', 'Uterus (endometrium)', 'Cervix', 'C', 'After fertilisation in the fallopian tube, the developing embryo travels to the uterus and implants in the endometrium (lining of the uterus).', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-777777777702', 'Biology', 'Reproduction', 'The hormone that maintains the endometrium during pregnancy is:', 'FSH', 'LH', 'Progesterone', 'Oestrogen only', 'C', 'Progesterone, secreted by the corpus luteum and later by the placenta, maintains the endometrial lining to support the developing embryo.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-777777777703', 'Biology', 'Reproduction', 'Binary fission is a method of reproduction found in:', 'Mammals', 'Bacteria', 'Birds', 'Ferns', 'B', 'Binary fission is the asexual reproduction method of bacteria, where the cell duplicates its DNA and splits into two identical daughter cells.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-777777777704', 'Biology', 'Reproduction', 'The process of oogenesis differs from spermatogenesis in that oogenesis produces:', 'Four equally sized functional gametes', 'One functional ovum and three polar bodies', 'Only two functional gametes', 'Haploid cells that are motile', 'B', 'In oogenesis, cytokinesis is unequal, resulting in one large functional ovum and two or three small polar bodies that degenerate.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-888888888801', 'Biology', 'Ecology', 'A group of individuals of the same species living in a given area is called a:', 'Community', 'Population', 'Ecosystem', 'Biome', 'B', 'A population consists of all individuals of one species in a particular area at a particular time.', 'easy'),
  ('a1b2c3d4-e5f6-7890-abcd-888888888802', 'Biology', 'Ecology', 'The maximum population size that an environment can sustain indefinitely is called the:', 'Biodiversity', 'Carrying capacity', 'Ecological niche', 'Biome capacity', 'B', 'Carrying capacity (K) is the maximum number of individuals of a species that an environment can support over time without degradation.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-888888888803', 'Biology', 'Ecology', 'The symbiotic relationship in which one organism benefits and the other is neither helped nor harmed is called:', 'Mutualism', 'Parasitism', 'Commensalism', 'Competition', 'C', 'In commensalism, one species benefits (e.g. barnacles on a whale) while the other species is unaffected.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-888888888804', 'Biology', 'Ecology', 'Deforestation primarily leads to:', 'Increased biodiversity', 'Loss of habitat, soil erosion and increased CO₂ levels', 'Enhanced water quality in nearby streams', 'Greater oxygen production', 'B', 'Removing trees destroys habitats, reduces photosynthesis (increasing CO₂), exposes soil to erosion, and disrupts water cycles.', 'medium'),
  ('a1b2c3d4-e5f6-7890-abcd-888888888805', 'Biology', 'Ecology', 'Which of the following is an example of an abiotic factor in an ecosystem?', 'Predation', 'Sunlight', 'Parasitism', 'Migration', 'B', 'Abiotic factors are the non-living components of an ecosystem — sunlight, temperature, water, pH, wind — that influence living organisms.', 'easy'),
  ('3aea5fc4-e954-5d57-b31e-c24014e5ed73', 'Chemistry', 'Atomic Structure', 'The subatomic particle that has no charge and is found in the nucleus is the:', 'Positron', 'Proton', 'Neutron', 'Electron', 'C', 'Neutrons are electrically neutral and, with protons, make up the nucleus.', 'easy'),
  ('c06f3f5c-4ecf-5047-9178-18c50bfc29a6', 'Chemistry', 'Atomic Structure', 'The atomic number of an element is equal to its number of:', 'Nucleons', 'Neutrons', 'Protons', 'Outer-shell electrons only', 'C', 'The atomic number (Z) is the number of protons in the nucleus, which defines the element.', 'easy'),
  ('fbd51a89-f3be-5a19-ad63-dda5030554f6', 'Chemistry', 'Atomic Structure', 'Isotopes of an element have the same number of protons but different numbers of:', 'Protons and electrons only', 'Neutrons', 'Electrons', 'Shells', 'B', 'Isotopes share the same atomic number (protons) but differ in mass number (neutrons), e.g. C-12 and C-14.', 'medium'),
  ('6c546bdc-7db6-5419-9afa-f4f7ecec3575', 'Chemistry', 'Atomic Structure', 'The maximum number of electrons the second (L) shell can hold is:', '32', '18', '2', '8', 'D', 'Electron shell capacities: first 2, second 8, third 18, fourth 32.', 'easy'),
  ('63cae0b8-f083-517d-8b9f-588296205701', 'Chemistry', 'Atomic Structure', 'Which of the following is NOT a fundamental subatomic particle of an atom?', 'Proton', 'Neutron', 'Electron', 'Photon', 'D', 'Protons, neutrons and electrons are subatomic particles; a photon is a quantum of light, not part of the atom.', 'medium'),
  ('001ed060-e822-576f-a72f-5d4f8a9756bd', 'Chemistry', 'Atomic Structure', 'In the modern periodic table, elements are arranged in order of increasing:', 'Atomic mass', 'Atomic number', 'Number of isotopes', 'Atomic weight only', 'B', 'The modern periodic table orders elements by increasing atomic number (protons).', 'medium'),
  ('c707ebe8-508c-522a-a139-708d4c786b81', 'Chemistry', 'Chemical Bonding', 'The bond formed when two atoms share a pair of electrons is called a:', 'Ionic bond', 'Hydrogen bond', 'Covalent bond', 'Metallic bond', 'C', 'A covalent bond forms when atoms share a pair of electrons. Ionic bonds involve electron transfer.', 'easy'),
  ('b1bda52b-a8cc-5eca-8e82-ea5db7496b55', 'Chemistry', 'Chemical Bonding', 'Sodium chloride (NaCl) is held together by which type of bond?', 'Covalent', 'Metallic', 'Co-ordinate', 'Ionic', 'D', 'NaCl is ionic: sodium donates an electron to chlorine, forming oppositely charged ions held by electrostatic attraction.', 'easy'),
  ('12eed8cd-2a00-5355-9a95-66bc07050121', 'Chemistry', 'Chemical Bonding', 'A hydrogen bond is:', 'An ionic bond', 'A metallic bond', 'A strong covalent bond', 'A weak attraction between a hydrogen atom and an electronegative atom (O, N, F)', 'D', 'Hydrogen bonds are weak intermolecular attractions, important in water and between DNA base pairs.', 'medium'),
  ('2ed0f60d-7b36-5fc2-ac29-1347b068a097', 'Chemistry', 'Chemical Bonding', 'Which molecule has a polar covalent bond?', 'Cl₂', 'O₂', 'HCl', 'H₂', 'C', 'In HCl the more electronegative chlorine pulls the shared electron pair, making the bond polar. H2/O2/Cl2 are nonpolar (identical atoms).', 'medium'),
  ('1f7895b2-656e-5657-8574-d71f1a9e9896', 'Chemistry', 'Chemical Bonding', 'In a co-ordinate (dative) bond, the shared pair of electrons is:', 'Delocalised over the whole molecule', 'Split equally from both atoms', 'Always donated by a metal', 'Provided by only one atom', 'D', 'In a dative bond one atom (the donor) supplies both shared electrons, e.g. in forming the ammonium ion.', 'hard'),
  ('fea66564-8fe7-52c0-8426-a7545922b81d', 'Chemistry', 'States of Matter', 'Which state of matter has a definite shape and a definite volume?', 'Solid', 'Liquid', 'Gas', 'Plasma', 'A', 'Solids have fixed shape and volume because their particles are packed in a fixed arrangement.', 'easy'),
  ('85260644-f68b-5a4b-aea3-3c8de1a31d04', 'Chemistry', 'States of Matter', 'The change of a liquid into a gas at the surface below its boiling point is called:', 'Melting', 'Condensation', 'Sublimation', 'Evaporation', 'D', 'Evaporation is the liquid–to–gas change at the surface below the boiling point.', 'medium'),
  ('22c6c6c7-1c22-57b6-9b95-dd1ac2cd27c8', 'Chemistry', 'States of Matter', 'The direct change of a solid into a gas, skipping the liquid state, is called:', 'Melting', 'Evaporation', 'Condensation', 'Sublimation', 'D', 'Sublimation is solid → gas directly, e.g. dry ice (solid CO2) and iodine.', 'medium'),
  ('62aeef98-e31b-5a45-aa35-d1b7dd21f46c', 'Chemistry', 'States of Matter', 'At constant volume, the pressure of a gas is directly proportional to its absolute temperature. This is:', 'Boyle''s law', 'Dalton''s law', 'Gay-Lussac''s (pressure) law', 'Charles'' law', 'C', 'At constant volume, P ∝ T (absolute). Boyle''s law is P ∝ 1/V at constant T; Charles'' law is V ∝ T at constant P.', 'hard'),
  ('a561d1f8-c5ec-524a-908f-ca10233fa96b', 'Chemistry', 'Chemical Energetics', 'A reaction that releases heat to the surroundings is called:', 'Catalytic', 'Endothermic', 'Irreversible only', 'Exothermic', 'D', 'Exothermic reactions release energy as heat and have a negative ΔH. Endothermic reactions absorb energy.', 'easy'),
  ('2d7c3471-5f37-582e-bb24-350ba3ef8a51', 'Chemistry', 'Chemical Energetics', 'A catalyst increases the rate of a reaction by:', 'Increasing activation energy', 'Consuming the reactants', 'Lowering activation energy', 'Raising the temperature permanently', 'C', 'Catalysts offer an alternative pathway with lower activation energy, speeding the reaction without being consumed.', 'medium'),
  ('cbf6dd81-7679-5c34-8a6f-b1a55675b842', 'Chemistry', 'Chemical Energetics', 'The minimum energy needed for a reaction to begin is called:', 'Enthalpy', 'Bond energy', 'Ionisation energy', 'Activation energy', 'D', 'Activation energy (Ea) is the minimum energy colliding molecules need to break bonds and start the reaction.', 'easy'),
  ('188b6e03-20db-50f3-a34b-f23105d3328f', 'Chemistry', 'Chemical Equilibrium', 'At equilibrium in a reversible reaction, the rates of the forward and backward reactions are:', 'Forward greater than backward', 'Always increasing', 'Equal', 'Zero', 'C', 'At dynamic equilibrium the forward and reverse reactions proceed at equal rates and concentrations stay constant.', 'medium'),
  ('6be37c2f-60b9-5a05-82c2-8d9627cb4bea', 'Chemistry', 'Chemical Equilibrium', 'According to Le Chatelier''s principle, raising the temperature of an endothermic reaction at equilibrium:', 'Shifts equilibrium to favour products', 'Has no effect', 'Always lowers both yields', 'Shifts equilibrium to favour reactants', 'A', 'Endothermic reactions absorb heat, so adding heat (raising T) shifts equilibrium toward products.', 'hard'),
  ('113457f7-10c6-5a75-805a-c4f6eb66b7d3', 'Chemistry', 'Acids and Bases', 'Which of the following is a strong acid?', 'Acetic acid (CH₃COOH)', 'Citric acid', 'Carbonic acid (H₂CO₃)', 'Hydrochloric acid (HCl)', 'D', 'HCl ionises almost completely in water (≈99%), making it a strong acid. Acetic, carbonic and citric are weak.', 'easy'),
  ('0cd67b3e-9f74-5d3c-a4cb-505d1eb27930', 'Chemistry', 'Acids and Bases', 'The pH of a neutral solution at 25°C is:', '1', '14', '7', '0', 'C', 'Pure water has pH 7 at 25°C — the neutral point on the 0–14 scale.', 'easy'),
  ('d0f74a7f-fefa-538b-9ec9-a3f0633929a1', 'Chemistry', 'Acids and Bases', 'A solution with a pH of 3 is:', 'Acidic', 'Basic', 'Neutral', 'Amphoteric', 'A', 'pH below 7 is acidic, so pH 3 is strongly acidic.', 'easy'),
  ('01f07e93-2a73-5b0b-93fa-855dafe3f44f', 'Chemistry', 'Electrochemistry', 'During the electrolysis of water, the gas released at the anode is:', 'Chlorine', 'Hydrogen', 'Nitrogen', 'Oxygen', 'D', 'At the anode (positive) oxygen gas is produced; hydrogen is released at the cathode.', 'medium'),
  ('4b4fefa2-bdd5-511f-b4e6-5f5bd3bea43b', 'Chemistry', 'Electrochemistry', 'In a galvanic (electrochemical) cell, oxidation always occurs at the:', 'Anode', 'Salt bridge', 'Electrolyte', 'Cathode', 'A', 'Oxidation (loss of electrons) occurs at the anode; reduction (gain of electrons) at the cathode.', 'hard'),
  ('ee3b5692-cc97-5dc1-9ef0-5723e6efd592', 'Chemistry', 'Organic Chemistry', 'The general formula of alkanes (saturated hydrocarbons) is:', 'CnH2n+2', 'CnH2n', 'CnH2n−2', 'CnHn', 'A', 'Alkanes have the formula CnH2n+2, e.g. methane CH4, ethane C2H6.', 'medium'),
  ('bc7f2cc3-6ef8-529a-9ba9-58e18f056c3a', 'Chemistry', 'Organic Chemistry', 'Which of the following is the simplest alkane?', 'Ethane', 'Ethene', 'Propane', 'Methane', 'D', 'Methane (CH4) is the simplest alkane; ethene is an alkene (CnH2n).', 'easy'),
  ('b3e37f9f-d27c-5258-94ba-c6242c0538a1', 'Chemistry', 'Organic Chemistry', 'The functional group of an alcohol is:', '–NH₂', '–OH', '–CHO', '–COOH', 'B', 'Alcohols contain the hydroxyl group –OH (e.g. ethanol C2H5OH). –COOH is a carboxylic acid.', 'easy'),
  ('8ba2b085-6edd-5143-81b1-3a38de6c8e5c', 'Chemistry', 'Organic Chemistry', 'The functional group –COOH defines which class of organic compounds?', 'Ketones', 'Carboxylic acids', 'Alcohols', 'Aldehydes', 'B', 'The carboxyl group –COOH defines carboxylic acids, e.g. acetic acid CH3COOH.', 'easy'),
  ('eaf06d03-0741-5ec7-a94c-14e91c65d4eb', 'Chemistry', 's and p Block Elements', 'The Group 1 alkali metals have how many electrons in their outermost shell?', '1', '2', '7', '3', 'A', 'Alkali metals (Li, Na, K, Rb, Cs) have one valence electron, which they readily lose to form +1 ions.', 'easy'),
  ('8eab3a29-8c4b-53a5-96e7-7b3837e53820', 'Chemistry', 's and p Block Elements', 'The most abundant gas in Earth''s atmosphere (about 78%) is:', 'Nitrogen', 'Carbon dioxide', 'Argon', 'Oxygen', 'A', 'Nitrogen (N2) makes up about 78% of the atmosphere; oxygen about 21%.', 'easy'),
  ('1bd31396-5e4d-5193-b6a2-c6a911e553ee', 'Chemistry', 's and p Block Elements', 'Halogens (Group 17) are highly reactive because they:', 'Have no outer electrons', 'Are noble gases', 'Gain one electron to complete their outer shell', 'Lose one electron easily', 'C', 'Halogens have seven valence electrons and readily gain one to form –1 ions (e.g. Cl–).', 'medium'),
  ('59e9e186-cad4-588f-8362-e8a2c15b83f0', 'Chemistry', 's and p Block Elements', 'Noble gases are almost unreactive because they:', 'Have a full outer shell of electrons', 'Are metals', 'Have no electrons', 'Are liquids at room temperature', 'A', 'Noble gases have a complete outer shell (stable octet or duet), making them very unreactive.', 'easy'),
  ('cee1eb41-c526-5a38-a5e6-e7b91df360dd', 'Chemistry', 'Hydrocarbons and Fuels', 'The process that breaks large hydrocarbons into smaller, more valuable molecules (e.g. to make petrol) is:', 'Fractional distillation', 'Hydrogenation', 'Polymerisation', 'Cracking', 'D', 'Cracking breaks large hydrocarbon molecules into smaller ones to produce petrol and alkenes.', 'medium'),
  ('a1b2c3d4-e5f6-4a7b-8c9d-0e1f2a3b4c5d', 'Chemistry', 'Atomic Structure', 'The mass number of an atom is the sum of:', 'Protons and electrons', 'Protons and neutrons', 'Neutrons and electrons', 'Only neutrons', 'B', 'Mass number (A) = protons + neutrons. Electrons have negligible mass.', 'easy'),
  ('b2c3d4e5-f6a7-4b8c-9d0e-1f2a3b4c5d6e', 'Chemistry', 'Atomic Structure', 'Which quantum number describes the shape of an orbital?', 'Principal quantum number (n)', 'Magnetic quantum number (m)', 'Angular momentum quantum number (l)', 'Spin quantum number (s)', 'C', 'The angular momentum quantum number (l) determines orbital shape: l=0 is s, l=1 is p, l=2 is d.', 'medium'),
  ('c3d4e5f6-a7b8-4c9d-0e1f-2a3b4c5d6e7f', 'Chemistry', 'Atomic Structure', 'An atom of carbon-14 has:', '6 protons, 6 neutrons, 6 electrons', '6 protons, 8 neutrons, 6 electrons', '8 protons, 6 neutrons, 8 electrons', '14 protons, 0 neutrons, 14 electrons', 'B', 'Carbon always has 6 protons. Mass number 14 means 14 − 6 = 8 neutrons. Neutral atom has 6 electrons.', 'medium'),
  ('d4e5f6a7-b8c9-4d0e-1f2a-3b4c5d6e7f80', 'Chemistry', 'Atomic Structure', 'The Aufbau principle states that electrons fill orbitals starting from:', 'The highest energy level', 'Any orbital at random', 'The orbital with the most electrons', 'The lowest energy level upward', 'D', 'Aufbau (German for "building up") means electrons occupy the lowest energy orbitals first.', 'medium'),
  ('e5f6a7b8-c9d0-4e1f-2a3b-4c5d6e7f8091', 'Chemistry', 'Atomic Structure', 'The number of radial nodes in an orbital is given by:', 'n − l', 'n + l', 'n − l − 1', '2n − 1', 'C', 'Radial nodes = n − l − 1. For a 3p orbital (n=3, l=1), radial nodes = 3 − 1 − 1 = 1.', 'hard'),
  ('f6a7b8c9-d0e1-4f2a-3b4c-5d6e7f809102', 'Chemistry', 'Chemical Bonding', 'The octet rule states that atoms tend to combine so that:', 'They have no electrons', 'They have a double outer shell', 'Each atom has an equal number of protons', 'Each atom attains the electron configuration of a noble gas', 'D', 'The octet rule: atoms gain, lose or share electrons to achieve a full outer shell (noble gas configuration).', 'easy'),
  ('a7b8c9d0-e1f2-4a3b-4c5d-6e7f80910213', 'Chemistry', 'Chemical Bonding', 'Which of the following molecules has a triple bond?', 'H₂', 'O₂', 'N₂', 'Cl₂', 'C', 'N₂ has a triple bond (N≡N), one of the strongest bonds, making nitrogen gas relatively inert.', 'easy'),
  ('b8c9d0e1-f2a3-4b4c-5d6e-7f8091021324', 'Chemistry', 'Chemical Bonding', 'In terms of hybridisation, the carbon atom in methane (CH₄) is:', 'sp hybridised', 'sp² hybridised', 'sp³ hybridised', 'Not hybridised', 'C', 'Methane has four equivalent C–H bonds arranged tetrahedrally (109.5°), which requires sp³ hybridisation.', 'medium'),
  ('c9d0e1f2-a3b4-4c5d-6e7f-809102132435', 'Chemistry', 'Chemical Bonding', 'VSEPR theory predicts the shape of a water molecule is:', 'Linear', 'Tetrahedral', 'Trigonal planar', 'Bent (V-shaped)', 'D', 'Water has two bonding pairs and two lone pairs on oxygen, giving a bent shape (~104.5° bond angle).', 'medium'),
  ('d0e1f2a3-b4c5-4d6e-7f80-910213243546', 'Chemistry', 'Chemical Bonding', 'Which of the following is an electrophile?', 'OH⁻', 'NH₃', 'BF₃', 'Cl⁻', 'C', 'BF₃ has an incomplete octet on boron, making it electron-pair accepting (electrophile). OH⁻ and Cl⁻ are nucleophiles.', 'hard'),
  ('e1f2a3b4-c5d6-4e7f-8091-021324354657', 'Chemistry', 'Chemical Bonding', 'The bond angle in ammonia (NH₃) is approximately:', '180°', '107°', '109.5°', '120°', 'B', 'NH₃ has three bonding pairs and one lone pair on nitrogen. Lone pair repulsion reduces the angle from 109.5° to about 107°.', 'hard'),
  ('f2a3b4c5-d6e7-4f80-9102-132435465768', 'Chemistry', 'Chemical Energetics', 'The enthalpy change when one mole of water is formed from its elements in their standard states is called:', 'Heat of combustion', 'Enthalpy of vaporisation', 'Standard enthalpy of formation of water', 'Bond enthalpy', 'C', 'The standard enthalpy of formation (ΔHf°) is the enthalpy change when 1 mol of a compound is formed from its elements in their standard states.', 'medium'),
  ('a3b4c5d6-e7f8-4091-0213-243546576879', 'Chemistry', 'Chemical Energetics', 'In an exothermic reaction:', 'Energy is absorbed from surroundings', 'The products have higher enthalpy than reactants', 'The surroundings get colder', 'The enthalpy change (ΔH) is negative', 'D', 'Exothermic reactions release heat; ΔH is negative because products are lower in enthalpy than reactants.', 'easy'),
  ('b4c5d6e7-f809-4102-1324-354657687980', 'Chemistry', 'Chemical Energetics', 'Hess''s law states that the total enthalpy change for a reaction is:', 'Dependent on the reaction pathway', 'Different if the reaction is carried out in steps', 'The same whether it occurs in one step or several steps', 'Zero for all reactions', 'C', 'Hess''s law: enthalpy is a state function, so the total ΔH depends only on initial and final states, not the path.', 'medium'),
  ('c5d6e7f8-0910-4213-2435-465768798091', 'Chemistry', 'Chemical Energetics', 'The bond dissociation energy of a Cl–Cl bond is approximately:', '432 kJ/mol', '242 kJ/mol', '151 kJ/mol', '498 kJ/mol', 'B', 'The Cl–Cl bond dissociation energy is about 242 kJ/mol, which is weaker than F–F (159) and stronger than I–I (151).', 'hard'),
  ('d6e7f809-1021-4324-3546-576879809102', 'Chemistry', 'Chemical Energetics', 'The standard enthalpy of combustion of a substance is measured when:', 'One gram of the substance is burned', 'One mole of the substance burns completely in excess oxygen under standard conditions', 'The substance is dissolved in water', 'The substance reacts with an acid', 'B', 'Standard enthalpy of combustion (ΔHc°): the enthalpy change when 1 mol of a substance burns completely in O₂ at standard conditions.', 'medium'),
  ('e7f80910-2132-4435-4657-687980910213', 'Chemistry', 'Chemical Energetics', 'Which process is endothermic?', 'Combustion of methane', 'Neutralisation of an acid with a base', 'Evaporation of water', 'Condensation of steam', 'C', 'Evaporation requires heat input from surroundings to overcome intermolecular forces, making it endothermic.', 'easy'),
  ('f8091021-3243-4546-5768-798091021324', 'Chemistry', 'Chemical Equilibrium', 'The equilibrium constant Kc for the reaction A + B ⇌ C + D is given by:', '[A][B] / [C][D]', '[C][D] / [A][B]', '[A] + [B] / [C] + [D]', '[C] + [D] / [A] + [B]', 'B', 'Kc = [products] / [reactants] = [C][D] / [A][B], each raised to their stoichiometric coefficients.', 'easy'),
  ('09102132-4354-4657-6879-809102132435', 'Chemistry', 'Chemical Equilibrium', 'For the reaction N₂(g) + 3H₂(g) ⇌ 2NH₃(g), increasing pressure at constant temperature will:', 'Shift equilibrium to the left', 'Shift equilibrium to the right', 'Have no effect on equilibrium', 'Increase the value of Kc', 'B', 'The forward reaction reduces total moles of gas (4 → 2). Increasing pressure favours the side with fewer gas moles (products).', 'hard'),
  ('10213243-5465-4768-7980-910213243546', 'Chemistry', 'Chemical Equilibrium', 'Adding a catalyst to a reaction at equilibrium will:', 'Shift equilibrium to the right', 'Increase the value of Kc', 'Shift equilibrium to the left', 'Not change the position of equilibrium', 'D', 'A catalyst speeds up both forward and reverse reactions equally, reaching equilibrium faster but not changing the position.', 'medium'),
  ('21324354-6576-4879-8091-021324354657', 'Chemistry', 'Chemical Equilibrium', 'If Kc >> 1 for a reaction, the equilibrium mixture contains mostly:', 'Reactants', 'Products', 'Equal amounts of reactants and products', 'Only catalyst', 'B', 'A large Kc means products are favoured at equilibrium, so the mixture is product-rich.', 'easy'),
  ('32435465-7687-4980-9102-132435465768', 'Chemistry', 'Chemical Equilibrium', 'The reaction quotient Q is used to:', 'Calculate the temperature of a reaction', 'Determine if a system is at equilibrium and which direction it will shift', 'Measure the activation energy', 'Find the molecular weight of a product', 'B', 'If Q < K, reaction proceeds forward; if Q > K, it shifts backward; if Q = K, the system is at equilibrium.', 'medium'),
  ('43546576-8798-4091-0213-243546576879', 'Chemistry', 'Chemical Equilibrium', 'For an exothermic reaction, increasing the temperature:', 'Increases the value of Kc', 'Has no effect on Kc', 'Shifts equilibrium to the left', 'Shifts equilibrium to the right', 'C', 'Raising temperature favours the endothermic (reverse) direction in an exothermic reaction, reducing Kc.', 'hard'),
  ('54657687-9809-4102-1324-354657687980', 'Chemistry', 'Acids and Bases', 'A buffer solution resists changes in pH when:', 'A strong acid is added', 'Small amounts of acid or base are added', 'It is heated to boiling', 'A large volume of water is added', 'B', 'Buffers (weak acid + conjugate base, or vice versa) neutralise small additions of acid or base, maintaining pH.', 'medium'),
  ('65768798-0910-4213-2435-465768798091', 'Chemistry', 'Acids and Bases', 'The conjugate base of H₂SO₄ is:', 'H₂SO₃', 'HSO₄⁻', 'SO₄²⁻', 'OH⁻', 'B', 'When H₂SO₄ donates one proton, it becomes HSO₄⁻ (its conjugate base).', 'medium'),
  ('76879809-1021-4324-3546-576879809102', 'Chemistry', 'Acids and Bases', 'The pH of a 0.01 M HCl solution is:', '1', '3', '2', '0', 'C', 'HCl is a strong acid: [H⁺] = 0.01 M = 10⁻² M. pH = −log(10⁻²) = 2.', 'medium'),
  ('87980910-2132-4435-4657-687980910213', 'Chemistry', 'Acids and Bases', 'An indicator that changes colour at pH 7 is:', 'Methyl orange (3.1–4.4)', 'Litmus (≈6–8)', 'Phenolphthalein (8.2–10)', 'Universal indicator (1–14)', 'B', 'Litmus changes around pH 6–8, making it suitable for detecting neutrality. Methyl orange changes at lower pH.', 'easy'),
  ('98091021-3243-4546-5768-798091021324', 'Chemistry', 'Acids and Bases', 'Which salt is formed when sodium hydroxide reacts with hydrochloric acid?', 'Sodium sulphate', 'Sodium carbonate', 'Sodium chloride', 'Sodium nitrate', 'C', 'NaOH + HCl → NaCl + H₂O. The salt is sodium chloride.', 'easy'),
  ('0b3ca965-9595-5935-a9f4-6d38546b0a63', 'Chemistry', 'Acids and Bases', 'The Lewis definition of an acid is a substance that:', 'Donates a proton', 'Accepts a proton', 'Donates an electron pair', 'Accepts an electron pair', 'D', 'A Lewis acid accepts an electron pair (e.g. BF₃), while a Lewis base donates an electron pair (e.g. NH₃).', 'hard'),
  ('7db209a9-9119-57bb-82ed-22f42b039edb', 'Chemistry', 'Acids and Bases', 'The hydrolysis of sodium carbonate solution makes it:', 'Acidic', 'Neutral', 'Basic', 'Amphoteric', 'C', 'Na₂CO₃ is a salt of a strong base (NaOH) and weak acid (H₂CO₃). Carbonate hydrolysis produces OH⁻, making the solution basic.', 'medium'),
  ('fb175ae3-13e6-5b15-90e1-c394110b1def', 'Chemistry', 's and p Block Elements', 'Which of the following alkali metals reacts most vigorously with water?', 'Lithium', 'Sodium', 'Potassium', 'Rubidium', 'D', 'Reactivity increases down Group 1. Rubidium reacts more vigorously than K, Na, or Li.', 'medium'),
  ('c03c44dd-6ccc-5eb8-b1e3-e75b6aaa8e5e', 'Chemistry', 's and p Block Elements', 'The formula of calcium oxide is CaO because:', 'Ca has 2 valence electrons and O needs 2', 'Ca forms covalent bonds easily', 'O has 1 valence electron', 'Ca has 7 valence electrons', 'A', 'Calcium (Group 2) loses 2 electrons to form Ca²⁺; oxygen (Group 16) gains 2 to form O²⁻. Opposite charges attract.', 'easy'),
  ('942e396c-9178-58e2-9f20-70d497f56bc6', 'Chemistry', 's and p Block Elements', 'Aluminium oxide (Al₂O₃) is described as amphoteric because it:', 'Only reacts with acids', 'Only reacts with bases', 'Does not react with either acids or bases', 'Reacts with both acids and bases', 'D', 'Amphoteric substances react with both acids and bases. Al₂O₃ dissolves in both HCl and NaOH.', 'medium'),
  ('91d8d122-70ac-5f53-82eb-4a30277ea9a4', 'Chemistry', 's and p Block Elements', 'Which of the following is a property of transition metals?', 'They form only one oxidation state', 'They form coloured compounds', 'They are always non-magnetic', 'They are poor conductors of electricity', 'B', 'Transition metals form coloured compounds due to d–d electron transitions and can exhibit multiple oxidation states.', 'easy'),
  ('5b9c6ec9-1549-5b5f-b2ac-aa5da082df27', 'Chemistry', 's and p Block Elements', 'The diagonal relationship in the periodic table exists between:', 'Elements in the same group', 'Elements in the same period', 'Elements in Group 1 and Group 2', 'Elements of period 2 and period 3 diagonally (e.g. Li and Mg)', 'D', 'Diagonal relationship: elements like Li/Mg, Be/Al, B/Si show similar properties due to comparable charge density.', 'hard'),
  ('9c523a82-b90d-5487-8670-5994221b1553', 'Chemistry', 's and p Block Elements', 'Which gas is released when dilute hydrochloric acid reacts with calcium carbonate?', 'Oxygen', 'Hydrogen', 'Nitrogen', 'Carbon dioxide', 'D', 'CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂↑. Carbon dioxide gas is released.', 'easy'),
  ('cd78d8a5-0241-505e-b361-6b9030b26cf8', 'Chemistry', 'Organic Chemistry', 'The IUPAC name of CH₃CH₂OH is:', 'Methanol', 'Ethanoic acid', 'Ethanol', 'Dimethyl ether', 'C', 'CH₃CH₂OH has two carbons and an –OH group, so it is ethanol (ethan-1-ol).', 'easy'),
  ('c9b31541-1d83-58a6-835e-ac293a5757a7', 'Chemistry', 'Organic Chemistry', 'Which test is used to distinguish an aldehyde from a ketone?', 'Bromine water test', 'Tollen''s reagent test', 'Iodoform test', 'Baeyer''s test', 'B', 'Tollen''s reagent (ammoniacal silver nitrate) gives a silver mirror with aldehydes but not with ketones.', 'medium'),
  ('8c5d83a6-5ffa-5cf7-867a-58c9e70d5465', 'Chemistry', 'Organic Chemistry', 'Polyethene is formed by the polymerisation of:', 'Ethane', 'Ethene', 'Ethanol', 'Ethyne', 'B', 'Ethene (CH₂=CH₂) undergoes addition polymerisation to form polyethene (polyethylene).', 'easy'),
  ('98c5d1c3-9a3f-5dcd-88bc-6036be075e92', 'Chemistry', 'Organic Chemistry', 'Which of the following is an ester?', 'CH₃COOH', 'CH₃COOCH₃', 'CH₃CHO', 'CH₃OH', 'B', 'CH₃COOCH₃ (methyl ethanoate) is an ester, formed by the reaction of acetic acid with methanol.', 'medium'),
  ('d9a8def7-cdcd-523c-8097-e44fbaf595c6', 'Chemistry', 'Organic Chemistry', 'The reaction of an alkene with hydrogen in the presence of a nickel catalyst is called:', 'Dehydrogenation', 'Halogenation', 'Hydrogenation', 'Hydration', 'C', 'Hydrogenation adds H₂ across a double bond. Ethene + H₂ → ethane (with Ni catalyst).', 'medium'),
  ('5b457aa0-5978-59e1-8166-378a4b11ee17', 'Chemistry', 'Organic Chemistry', 'The number of structural isomers of butane (C₄H₁₀) is:', '1', '2', '3', '4', 'B', 'C₄H₁₀ has two structural isomers: n-butane (straight chain) and isobutane (2-methylpropane).', 'medium'),
  ('48c8db1a-2128-50e6-9965-c69256215ab1', 'Chemistry', 'Electrochemistry', 'The electrode where reduction takes place is called the:', 'Anode', 'Cathode', 'Salt bridge', 'Voltmeter', 'B', 'Reduction always occurs at the cathode; oxidation at the anode.', 'easy'),
  ('bb229cfa-1ca6-557a-88c6-bb797000ff45', 'Chemistry', 'Electrochemistry', 'The standard electrode potential of a zinc electrode is −0.76 V, and copper is +0.34 V. In a Daniell cell, the EMF is:', '0.42 V', '1.10 V', '−1.10 V', '0.76 V', 'B', 'EMF = E(cathode) − E(anode) = 0.34 − (−0.76) = 1.10 V.', 'hard'),
  ('45585810-2da9-5b12-9862-c273d61841f4', 'Chemistry', 'Electrochemistry', 'Faraday''s first law of electrolysis states that the mass deposited at an electrode is proportional to:', 'The voltage applied', 'The temperature', 'The resistance of the electrolyte', 'The quantity of electricity (charge) passed', 'D', 'm = (Q × M) / (n × F). Mass deposited is directly proportional to the charge (Q) passed through the electrolyte.', 'medium'),
  ('69e17bc7-4cb3-56c5-907d-f274767cbcff', 'Chemistry', 'Electrochemistry', 'In electroplating, the object to be plated is made the:', 'Cathode', 'Anode', 'Both anode and cathode', 'Neither electrode', 'A', 'The object is made the cathode so that metal ions from solution are reduced and deposited on its surface.', 'easy'),
  ('f3ddc671-240a-5a37-a77b-64d39da11313', 'Chemistry', 'States of Matter', 'According to Graham’s law of diffusion, the rate of diffusion of a gas is inversely proportional to the square root of its:', 'Temperature', 'Pressure', 'Molar mass', 'Volume', 'C', 'Graham’s law states rate ∝ 1/√M, so lighter gases (low molar mass) diffuse faster than heavier ones at the same temperature and pressure.', 'medium'),
  ('77d24450-bf86-51b7-b6a9-71c21ac202e2', 'Chemistry', 'States of Matter', 'The critical temperature of a gas is the temperature:', 'At which it freezes under any pressure', 'Above which it cannot be liquefied by pressure alone', 'At which it always condenses', 'Below which it always remains gaseous', 'B', 'Above the critical temperature the kinetic energy is too high for pressure alone to force molecules into the liquid state, no matter how high the pressure is raised.', 'hard'),
  ('efadbf25-19fb-5862-af44-48c08946d759', 'Chemistry', 'States of Matter', 'The latent heat of fusion is the heat energy required to:', 'Convert a liquid to vapour at constant temperature', 'Raise a solid’s temperature by 1 °C', 'Convert a solid to liquid at its melting point', 'Change a liquid’s temperature while boiling', 'C', 'Latent heat of fusion (melting) is the energy absorbed when one mole of solid changes to liquid at its melting point without a temperature change.', 'easy'),
  ('4b46cab3-6e35-5330-86aa-57bf6687dc11', 'Chemistry', 'States of Matter', 'Which of the following is an example of the plasma state of matter?', 'Dry ice', 'Mercury at room temperature', 'The gas inside a fluorescent lamp', 'Ice at 0 °C', 'C', 'A fluorescent lamp contains ionised gas; plasma is a collection of free-moving ions and electrons produced when a gas is energised.', 'medium'),
  ('85a934f7-1e63-5706-972f-b231fdaac865', 'Chemistry', 'States of Matter', 'Ice floats on water mainly because:', 'Water is more dense as a solid', 'Hydrogen bonding makes solid ice less dense than liquid water', 'Ice is warmer than liquid water', 'Water expands on freezing into a denser lattice', 'B', 'In ice, hydrogen bonds hold water molecules in an open hexagonal lattice that is less dense than liquid water, so ice floats.', 'medium'),
  ('7d07a23a-d990-5da9-9e06-182befec17f9', 'Chemistry', 'Hydrocarbons and Fuels', 'The octane number of a fuel measures its:', 'Heat content per litre', 'Resistance to knocking during combustion', 'Sulfur content', 'Density', 'B', 'Octane number rates a petrol’s resistance to premature auto-ignition (knock). Iso-octane is 100 and n-heptane is 0 on the scale.', 'medium'),
  ('9e9b59ca-3131-5f27-9195-7dd6797d3119', 'Chemistry', 'Hydrocarbons and Fuels', 'Cracking of long-chain alkanes is carried out to produce:', 'Smaller, more useful hydrocarbons and alkenes', 'Pure carbon', 'Only hydrogen gas', 'Larger cyclic hydrocarbons', 'A', 'Cracking breaks large alkanes into smaller alkanes and alkenes, including the short-chain molecules (e.g. petrol fractions and alkenes for polymers).', 'easy'),
  ('7b17f442-efe1-5c9d-8277-17e8645fa163', 'Chemistry', 'Hydrocarbons and Fuels', 'Which gas is the main greenhouse gas released by the complete combustion of fossil fuels?', 'Carbon dioxide', 'Nitrogen', 'Oxygen', 'Hydrogen sulfide', 'A', 'Complete combustion of carbon-containing fuels produces CO₂, the principal greenhouse gas linked to climate change.', 'easy'),
  ('85a117ee-38d2-57b4-8b97-e07a9453cb5c', 'Chemistry', 'Hydrocarbons and Fuels', 'Engine "knock" in a petrol engine is more likely when the fuel:', 'Has a high octane number', 'Ignites prematurely and burns unevenly', 'Is completely vaporised', 'Contains only iso-octane', 'B', 'Knock happens when part of the air-fuel mixture auto-ignites before the spark, producing a sharp pressure surge. High octane ratings suppress this.', 'medium'),
  ('b8e5014e-8994-5277-8836-ba46594bc63c', 'Chemistry', 'Hydrocarbons and Fuels', 'The main component of natural gas is:', 'Ethane', 'Propane', 'Butane', 'Methane', 'D', 'Natural gas is chiefly methane (CH₄), which burns cleanly and is widely used as a domestic and industrial fuel.', 'easy'),
  ('032a91c4-bb6c-5a34-ae8f-a695aad3042e', 'Chemistry', 'Electrochemistry', 'The standard hydrogen electrode (SHE) is assigned a reduction potential of:', '0.00 V', '+0.34 V', '−0.76 V', '+1.23 V', 'A', 'By convention the SHE (Pt electrode, H₂ gas at 1 atm, H⁺ at 1 M) is assigned a standard reduction potential of exactly 0.00 V.', 'easy'),
  ('2c6dae88-03bd-56d9-891a-7994d94082b1', 'Chemistry', 'Electrochemistry', 'The Nernst equation is used to calculate:', 'The equilibrium constant only', 'Cell potential under non-standard conditions', 'The rate constant of a reaction', 'The pH of a buffer', 'B', 'Nernst equation E = E° − (RT/nF)lnQ relates cell potential to ion concentrations and pressure when conditions depart from standard states.', 'medium'),
  ('95a9e3ef-cc4a-5c6e-9ab6-8361b76ab58b', 'Chemistry', 'Electrochemistry', 'In a galvanic (voltaic) cell, oxidation occurs at the:', 'Cathode', 'Anode', 'Salt bridge', 'External wire', 'B', 'In a galvanic cell the anode is the electrode where oxidation takes place; electrons flow from the anode to the cathode through the external circuit.', 'medium'),
  ('3741403e-c1dc-57d9-9f6d-7d969a70fff9', 'Chemistry', 'Electrochemistry', 'During the electrolysis of molten sodium chloride, the products at the electrodes are:', 'Sodium at the cathode and chlorine at the anode', 'Hydrogen and oxygen', 'Sodium and oxygen', 'Chlorine and hydrogen', 'A', 'Molten NaCl contains only Na⁺ and Cl⁻. Na⁺ is reduced to sodium metal at the cathode and Cl⁻ is oxidised to chlorine gas at the anode.', 'medium'),
  ('fcc94609-99e3-59d5-a6b2-dddb4e53151c', 'Chemistry', 'Electrochemistry', 'One faraday of charge (approximate value) is equal to:', '6.02 × 10²³ coulombs', '96,500 coulombs', '1 coulomb', '22.4 coulombs', 'B', 'One faraday is the charge carried by one mole of electrons, approximately 96,500 C (96485.3 C).', 'easy'),
  ('a1ec2f6a-e9eb-56cf-9982-2ee6b714b9d1', 'Chemistry', 'Electrochemistry', 'The oxidation number of manganese in KMnO₄ is:', '+2', '+4', '+6', '+7', 'D', 'In KMnO₄: K is +1, each O is −2 (total −8), so Mn must be +7 to balance the neutral compound.', 'medium'),
  ('83c02e82-f557-5140-b2ab-7b7c77148b2b', 'Chemistry', 'Atomic Structure', 'For a 3p electron, the values of the quantum numbers (n, l, mₗ) can be:', '(3, 1, 0)', '(3, 2, 1)', '(2, 1, 0)', '(3, 0, 0)', 'A', 'For a 3p subshell n = 3 and l = 1 (p). mₗ can be −1, 0, or +1, so (3, 1, 0) is a valid set.', 'hard'),
  ('80b22c2c-14fe-54be-a7fb-310ffa833435', 'Chemistry', 'Chemical Bonding', 'The bond order of the oxygen molecule O₂, according to molecular orbital theory, is:', '1', '2', '0', '3', 'B', 'O₂ has a bond order of (10 bonding − 6 antibonding) / 2 = 2, consistent with its double bond and paramagnetism.', 'medium'),
  ('264e885a-975c-59cb-be04-abef4c6a77de', 'Chemistry', 'Chemical Energetics', 'Hess’s law states that the enthalpy change of a reaction:', 'Depends only on the initial and final states, not the path taken', 'Depends on the number of intermediates', 'Is always positive', 'Is independent of temperature', 'A', 'Hess’s law: enthalpy is a state function, so total ΔH is the sum of ΔH of each step regardless of the pathway between reactants and products.', 'medium'),
  ('4b206bf9-aae7-5df6-af22-e313f70e54ee', 'Chemistry', 'Chemical Equilibrium', 'Adding a catalyst to a system at equilibrium:', 'Shifts the equilibrium to the product side', 'Increases the equilibrium constant', 'Speeds up the rate of approach to equilibrium without changing the equilibrium position', 'Permanently raises the yield of products', 'C', 'A catalyst lowers the activation energy for both forward and reverse directions equally, so it accelerates attainment of equilibrium without shifting its position or changing K.', 'medium'),
  ('2cf09a64-5be9-5f7a-8c1e-ef53b0f2b812', 'Chemistry', 'States of Matter', 'The pressure exerted by a gas results primarily from:', 'The weight of the gas molecules', 'Collisions of gas molecules with the container walls', 'Gravitational attraction between molecules', 'The volume of the individual molecules', 'B', 'Gas pressure arises from the force of countless molecular collisions against the container walls; this is the kinetic-molecular explanation of pressure.', 'easy'),
  ('39bb840d-f1a9-5a4f-a1d6-c0f42bb1c1e2', 'Chemistry', 'Hydrocarbons and Fuels', 'The octane rating of petrol can be improved by adding:', 'Pure water', 'Branched-chain alkanes and aromatic hydrocarbons', 'More nitrogen', 'Straight-chain alkanes', 'B', 'Branched alkanes and aromatics have high octane numbers (resist knocking), so adding them raises the fuel’s octane rating without harmful additives.', 'medium'),
  ('0e45ad92-c2f6-5f2c-b1d3-1c90b3f45cd8', 'Chemistry', 'Chemical Bonding', 'In the bond formation between hydrogen and chlorine in HCl, the bond is:', 'Pure ionic', 'Pure covalent', 'Polar covalent', 'Metallic', 'C', 'H and Cl share the electron pair (covalent) but Cl is more electronegative, so the shared pair is drawn toward Cl, making HCl a polar covalent bond.', 'easy'),
  ('e5c7c3d4-2b50-5c10-99f2-ba1998b0d2f1', 'Chemistry', 'Chemical Energetics', 'An exothermic reaction is characterised by:', 'A positive enthalpy change (ΔH > 0)', 'A negative enthalpy change (ΔH < 0)', 'No enthalpy change', 'An enthalpy change exactly equal to zero', 'B', 'Exothermic reactions release heat to the surroundings, so the products have lower enthalpy than the reactants and ΔH is negative.', 'easy'),
  ('82341e68-6b05-5c91-a9db-7f35c677b52a', 'Chemistry', 'Chemical Equilibrium', 'For the reaction N₂(g) + 3H₂(g) ⇌ 2NH₃(g), increasing the pressure will:', 'Shift equilibrium to favour NH₃ (fewer gas moles)', 'Shift equilibrium toward N₂ and H₂', 'Have no effect', 'Decompose NH₃ completely', 'A', 'Increasing pressure favours the side with fewer gas moles. Here the product side has 2 moles vs 4 on the reactant side, so NH₃ production is favoured (Le Chatelier).', 'medium'),
  ('af9c49aa-0f70-5010-b356-c0bb428f867f', 'Physics', 'Measurement', 'The SI unit of force is the:', 'Watt', 'Pascal', 'Newton', 'Joule', 'C', 'Force is measured in newtons (N): 1 N = 1 kg·m/s².', 'easy'),
  ('6d910043-e53f-5cac-a67f-aa9c6fa1d669', 'Physics', 'Measurement', 'The SI unit of energy is the:', 'Volt', 'Watt', 'Joule', 'Newton', 'C', 'Energy and work are measured in joules (J); power is measured in watts (J/s).', 'easy'),
  ('aefedc18-36a3-5a1a-b116-c3f1d9000bb8', 'Physics', 'Measurement', 'Which pair of quantities are vectors?', 'Speed and distance', 'Temperature and volume', 'Velocity and displacement', 'Mass and time', 'C', 'Vectors have both magnitude and direction (velocity, displacement, force, acceleration); scalars have only magnitude.', 'medium'),
  ('f0ab8497-7f8d-5ed0-8b88-eec449188043', 'Physics', 'Measurement', 'Which of the following is a scalar quantity?', 'Velocity', 'Acceleration', 'Speed', 'Force', 'C', 'Speed is scalar (magnitude only); velocity, force and acceleration have direction.', 'easy'),
  ('84e065f1-1b84-5126-957c-597120c6ce75', 'Physics', 'Measurement', 'The prefix “kilo” means a multiplier of:', '10³', '10⁶', '10²', '10⁻³', 'A', 'kilo- = ×10³ (1000), e.g. 1 km = 1000 m.', 'easy'),
  ('44cc5aa1-f4ef-5c4e-ba04-5693fbf04854', 'Physics', 'Measurement', 'A standard screw gauge reads accurately to:', '1 mm', '0.01 mm', '0.001 m', '0.1 mm', 'B', 'A screw gauge measures to 0.01 mm; a vernier calliper reads to about 0.1 mm.', 'hard'),
  ('11f2a17d-28f5-5a1b-bcc7-5d9fc6edfb91', 'Physics', 'Kinematics', 'Speed is defined as:', 'Force per unit area', 'Change in velocity per unit time', 'Displacement per unit time', 'Distance travelled per unit time', 'D', 'Speed = distance ÷ time (scalar). Velocity = displacement ÷ time (vector). Acceleration = change in velocity ÷ time.', 'easy'),
  ('e980a8e3-e6d2-5a33-9042-a6dabfd7e844', 'Physics', 'Kinematics', 'The SI unit of acceleration is:', 'm²/s', 'm/s', 'N/s', 'm/s²', 'D', 'Acceleration (change in velocity per time) is measured in metres per second squared (m/s²).', 'easy'),
  ('ced2bdad-c200-5432-9540-73fddd336f1d', 'Physics', 'Kinematics', 'A body moving with uniform (constant) velocity has:', 'Increasing speed', 'Decreasing speed', 'Zero acceleration', 'Constant positive acceleration', 'C', 'Constant velocity means acceleration (the rate of change of velocity) is zero.', 'medium'),
  ('111e0413-6486-57d8-9027-b25964f0ad9f', 'Physics', 'Kinematics', 'The acceleration of free fall near the Earth''s surface (g) is approximately:', '9.8 m/s²', '6.67 m/s²', '0 m/s²', '19.6 m/s²', 'A', 'g ≈ 9.8 m/s² on Earth, decreasing with altitude and depth.', 'easy'),
  ('95173d78-66dd-5e4a-a5d4-08b340d36c80', 'Physics', 'Kinematics', 'Ignoring air resistance, a freely falling body:', 'Moves at constant velocity', 'Accelerates downward at g', 'Slows down steadily', 'Stays at constant height', 'B', 'In free fall a body accelerates downward at g (≈9.8 m/s²), so its speed increases uniformly.', 'medium'),
  ('d6b890fb-4333-5a14-b7ec-10b2e69c5ad9', 'Physics', 'Dynamics', 'Newton''s first law of motion (the law of inertia) states that:', 'For every action there is an equal and opposite reaction', 'Momentum equals mass times velocity', 'F = ma', 'A body at rest stays at rest and a moving body keeps moving uniformly unless acted on by an external force', 'D', 'Newton''s first law: an object keeps its state of rest or uniform motion unless a net external force acts on it.', 'medium'),
  ('6276b65c-5540-5b1e-9b67-ff2dcc84d569', 'Physics', 'Dynamics', 'The mathematical form of Newton''s second law of motion is:', 'F = ma', 'F = mv', 'p = mv', 'v = u + at', 'A', 'Newton''s second law: net force equals mass times acceleration (F = ma).', 'easy'),
  ('8e64249a-257d-54d9-af4f-4f66ddb5fad4', 'Physics', 'Dynamics', 'According to Newton''s third law, forces always occur:', 'Independently of matter', 'As equal and opposite pairs', 'Only in gravity', 'Singularly', 'B', 'Every action has an equal and opposite reaction — forces come in action–reaction pairs on different bodies.', 'easy'),
  ('da642cae-afff-5b18-8bb9-099027c92a5c', 'Physics', 'Dynamics', 'The SI unit of momentum is:', 'kg·m/s', 'kg·m/s²', 'J/s', 'N·m', 'A', 'Momentum p = mv, giving the unit kg·m/s.', 'medium'),
  ('d419035d-ca52-55cf-8826-c95a9c1c922f', 'Physics', 'Dynamics', 'Friction always acts:', 'Only downward', 'Only on solids', 'In the direction of motion', 'Opposite to the direction of (attempted) motion', 'D', 'Friction opposes relative motion or the tendency to move between surfaces.', 'medium'),
  ('ec0f19f6-e18c-5e8e-8967-737586d1f636', 'Physics', 'Dynamics', 'Momentum is conserved in a collision when:', 'The temperature is constant', 'The collision is always elastic', 'The objects are identical', 'No external force acts on the system', 'D', 'The law of conservation of momentum holds when the net external force on the system is zero.', 'medium'),
  ('ce4bd6ac-dc97-5a39-b50d-8db00dfe2e79', 'Physics', 'Work and Energy', 'Work is done when:', 'A body moves with no force', 'Only when energy is stored', 'A force acts on a body', 'A force displaces a body in the direction of the force', 'D', 'Work = force × displacement along the direction of the force (W = Fd cosθ). A force producing no displacement does no work.', 'medium'),
  ('6b95fb80-0f5b-5676-9200-588532d09e20', 'Physics', 'Work and Energy', 'The SI unit of power is the:', 'Newton', 'Tesla', 'Joule', 'Watt', 'D', 'Power = work ÷ time, measured in watts (1 W = 1 J/s).', 'easy'),
  ('de90598f-1f98-54d3-bfbf-8b85d1518e24', 'Physics', 'Work and Energy', 'The kinetic energy of a body of mass m moving at speed v is:', 'mgh', 'mv²', '½mv²', 'mv', 'C', 'Kinetic energy KE = ½mv². Gravitational potential energy PE = mgh.', 'medium'),
  ('abfcb8e9-f6d9-526e-9d58-d69af5eb3fa3', 'Physics', 'Work and Energy', 'Potential energy is best described as:', 'Energy in sound waves', 'Energy of motion', 'Energy lost as heat', 'Stored energy due to position or configuration', 'D', 'Potential energy is stored energy due to position (mgh) or configuration (elastic).', 'easy'),
  ('2b5a0403-5066-5a2c-86f2-ce1d0ee4bb7b', 'Physics', 'Work and Energy', 'The law of conservation of energy states that energy:', 'Can be created', 'Is always kinetic', 'Can neither be created nor destroyed, only transformed', 'Can be destroyed', 'C', 'Energy is conserved — it changes form (potential ↔ kinetic, etc.) but the total stays constant.', 'easy'),
  ('c33cbf1a-3f02-5447-b807-52da88250c0a', 'Physics', 'Fluid Dynamics', 'The pressure exerted by a liquid increases with:', 'Lower liquid density', 'Increasing container surface area only', 'Increasing depth', 'Decreasing depth', 'C', 'Liquid pressure P = ρgh increases with depth (h) and density.', 'medium'),
  ('68c1520f-269f-505a-8e0b-e68ffb274b2d', 'Physics', 'Fluid Dynamics', 'The unit of pressure is the:', 'Watt', 'Joule', 'Pascal', 'Newton', 'C', 'Pressure = force ÷ area, measured in pascals (1 Pa = 1 N/m²).', 'easy'),
  ('a2015c7c-73ae-59dc-8e3c-3799187f42e8', 'Physics', 'Fluid Dynamics', 'Archimedes'' principle states that the upthrust on a submerged body equals:', 'The weight of the body', 'The weight of the fluid displaced', 'The density of the body', 'The volume of the body', 'B', 'The buoyant (upthrust) force equals the weight of the fluid the body displaces.', 'medium'),
  ('c6dc4714-6ca8-5890-8c10-bbabfa43095f', 'Physics', 'Oscillations and Waves', 'The time taken for one complete vibration of a wave is its:', 'Wavelength', 'Frequency', 'Amplitude', 'Period', 'D', 'The period (T) is the time for one complete cycle; frequency f = 1/T.', 'easy'),
  ('2968919c-a4bf-50e7-8ff4-dc73c339282c', 'Physics', 'Oscillations and Waves', 'The number of complete waves produced per second is the:', 'Speed', 'Wavelength', 'Frequency', 'Amplitude', 'C', 'Frequency (in Hz) is the number of complete oscillations or waves per second.', 'easy'),
  ('00ad794c-e729-5a06-a0e6-ab979a34f7f6', 'Physics', 'Oscillations and Waves', 'The relationship between wave speed v, frequency f and wavelength λ is:', 'v = fλ', 'v = f/λ', 'v = λ/f', 'v = 1/fλ', 'A', 'Wave speed v = frequency × wavelength (v = fλ).', 'medium'),
  ('ddc6a5f9-16d2-5aa4-bab7-39eae64a160d', 'Physics', 'Oscillations and Waves', 'Sound waves are an example of:', 'Electromagnetic waves', 'Longitudinal waves', 'Transverse waves', 'Stationary light waves', 'B', 'Sound is a longitudinal (compression) mechanical wave that needs a medium; light is a transverse EM wave.', 'easy'),
  ('de5d0321-ed1d-5ab4-803a-3715bf331df7', 'Physics', 'Light and Optics', 'The speed of light in a vacuum is approximately:', '3 × 10⁸ m/s', '3 × 10⁹ m/s', '3 × 10⁸ km/s', '300 m/s', 'A', 'Light travels at about 3×10⁸ m/s (300,000 km/s) in a vacuum.', 'easy'),
  ('56186bd1-44ab-5ca2-95e7-07650f1d66e7', 'Physics', 'Light and Optics', 'Light is a:', 'Mechanical sound wave', 'Transverse electromagnetic wave', 'Longitudinal mechanical wave', 'Compression wave', 'B', 'Light is a transverse electromagnetic wave and can travel through a vacuum.', 'medium'),
  ('6494b0a3-80bd-5fc3-a614-e96575408d2e', 'Physics', 'Light and Optics', 'The splitting of white light into its component colours by a prism is called:', 'Polarisation', 'Diffraction', 'Dispersion', 'Refraction', 'C', 'Dispersion separates white light into its spectrum (red to violet) because different wavelengths refract by different amounts.', 'medium'),
  ('cd8402c5-a127-5514-b282-5d54e5ed596a', 'Physics', 'Light and Optics', 'A concave lens always produces an image that is for a real object:', 'Virtual and larger', 'Virtual, upright and smaller', 'Real and inverted', 'Real and upright', 'B', 'A concave (diverging) lens always forms a virtual, upright, diminished image of a real object.', 'hard'),
  ('def64fcb-8d9c-53d3-8384-9328a0f3f459', 'Physics', 'Light and Optics', 'The power of a lens in dioptres is:', '1 / focal length (in metres)', 'Twice the focal length', 'The focal length', '1 / (focal length²)', 'A', 'Power (D) = 1 / f (metres). A lens of focal length 0.5 m has power 2 dioptres.', 'hard'),
  ('9045961a-3623-535b-aa0e-796e97e44b2a', 'Physics', 'Light and Optics', 'A reflection from a plane mirror produces an image that is:', 'Virtual, upright and laterally inverted', 'Brighter than the object', 'Virtual and upside down', 'Real and inverted', 'A', 'A plane mirror forms a virtual, upright image of the same size, laterally inverted (left–right reversed).', 'medium'),
  ('b8d29d3f-434e-52d8-ab6b-bef3d2ba99e8', 'Physics', 'Heat and Thermodynamics', 'Heat is a form of:', 'Electric charge', 'Energy', 'Matter', 'Force', 'B', 'Heat is thermal energy transferred between objects at different temperatures.', 'easy'),
  ('cf6a4d8a-5fdf-57bb-ad8f-6378e9170ad3', 'Physics', 'Heat and Thermodynamics', 'The three modes of heat transfer are:', 'Conduction, convection and radiation', 'Evaporation, boiling and melting', 'Reflection, refraction and diffraction', 'Oxidation, reduction and combustion', 'A', 'Heat transfers by conduction (contact), convection (fluid movement) and radiation (EM waves, no medium needed).', 'easy'),
  ('f9aa791e-0c6a-5c7d-8d3f-88054e3c0d29', 'Physics', 'Heat and Thermodynamics', 'Which mode of heat transfer can travel through a vacuum?', 'Sound', 'Conduction', 'Radiation', 'Convection', 'C', 'Radiation (infrared EM waves) transfers heat through a vacuum — e.g. heat from the Sun reaches Earth.', 'medium'),
  ('5df952db-7880-53d7-963a-989237f04586', 'Physics', 'Heat and Thermodynamics', 'The temperature at which molecular motion ideally stops is:', '0°C', '0 K (−273.15°C)', '100°C', '273 K', 'B', 'Absolute zero is 0 K or −273.15°C, the theoretical point of minimum energy.', 'medium'),
  ('48effe7e-f752-58c1-a63b-cbefe25b874b', 'Physics', 'Electricity and Magnetism', 'The SI unit of electric current is the:', 'Volt', 'Watt', 'Ampere', 'Ohm', 'C', 'Electric current is measured in amperes (A).', 'easy'),
  ('08059781-f692-5006-a11d-812f5384582c', 'Physics', 'Electricity and Magnetism', 'According to Ohm''s law:', 'V = IR', 'V = I/R', 'R = IV', 'I = VR', 'A', 'Ohm''s law: voltage = current × resistance (V = IR).', 'easy'),
  ('d1aec7f9-18c8-5db1-a190-cbb7b5051e74', 'Physics', 'Electricity and Magnetism', 'The unit of electrical resistance is the:', 'Coulomb', 'Volt', 'Ohm', 'Ampere', 'C', 'Resistance is measured in ohms (Ω).', 'easy'),
  ('c05bf45c-37a6-5f2d-94cc-4497a019aa6c', 'Physics', 'Electricity and Magnetism', 'Electric current is defined as:', 'The rate of flow of charge', 'The voltage across a wire', 'The energy per unit charge', 'The force per unit charge', 'A', 'Current I = charge ÷ time — the rate of flow of electric charge.', 'medium'),
  ('221655fb-59df-526d-9ede-25af4027b8eb', 'Physics', 'Electricity and Magnetism', 'In a series circuit the total resistance is:', 'The sum of the individual resistances', 'Always less than the smallest', 'Exactly the voltage', 'The reciprocal of the sum', 'A', 'Resistors in series add: R_total = R1 + R2 + R3 + …', 'medium'),
  ('92a8557b-0ef6-5e25-9d40-85599a8e90f9', 'Physics', 'Electricity and Magnetism', 'The device used to measure electric current in a circuit is the:', 'Voltmeter', 'Ammeter', 'Ohmmeter', 'Galvanometer', 'B', 'An ammeter (connected in series) measures current; a voltmeter (in parallel) measures potential difference.', 'medium'),
  ('8763918d-cde9-53c8-8fb0-15a6fdfb8a17', 'Physics', 'Electricity and Magnetism', 'Like magnetic poles ______ each other and unlike poles ______ each other.', 'repel; attract', 'attract; attract', 'repel; repel', 'attract; repel', 'A', 'Like poles repel and unlike (opposite) poles attract.', 'easy'),
  ('ec7b3a31-2f01-5671-94a4-a30dae6286d3', 'Physics', 'Magnetism', 'Electromagnetic induction was discovered by:', 'Michael Faraday', 'James Watt', 'Galileo', 'Isaac Newton', 'A', 'Faraday discovered electromagnetic induction — a changing magnetic field induces an EMF in a conductor.', 'medium'),
  ('b9b6b12f-2b1a-5689-91ae-d9bec9921af0', 'Physics', 'Modern Physics', 'The energy of a photon is directly proportional to its:', 'Charge', 'Wavelength', 'Speed', 'Frequency', 'D', 'Photon energy E = hf, so it is proportional to frequency.', 'medium'),
  ('e0e70cf2-12ed-5e34-93d4-73c3d8bb2f36', 'Physics', 'Modern Physics', 'The photoelectric effect provides evidence for:', 'The wave nature of light', 'The particle (photon) nature of light', 'Continuous wave energy only', 'Sound transmission', 'B', 'The photoelectric effect (Einstein, 1905) shows light behaves as discrete quanta (photons).', 'hard'),
  ('278ecbb8-1289-58b4-a66a-eb0c345d8d84', 'Physics', 'Modern Physics', 'The half-life of a radioactive substance is:', 'The time for half the radioactive nuclei to decay', 'The time to become fully stable', 'Always half its mass', 'Always 5730 years', 'A', 'Half-life is the time for half the radioactive nuclei in a sample to decay.', 'medium'),
  ('b1a2c3d4-e5f6-5a7b-8c9d-0e1f2a3b4c5d', 'Physics', 'Measurement', 'Which of the following has the most significant figures?', '2.50 m', '250 cm', '0.0025 km', '2500 mm', 'A', '2.50 has three significant figures (trailing zero after decimal counts). 250 has two, 0.0025 has two, and 2500 has two.', 'medium'),
  ('c2b3a4d5-e6f7-5a8b-9c0d-1e2f3a4b5c6d', 'Physics', 'Kinematics', 'A car accelerates from rest at 2 m/s² for 5 s. The distance covered is:', '10 m', '25 m', '50 m', '5 m', 'B', 'Using s = ut + ½at²: s = 0 + ½(2)(5²) = 25 m.', 'medium'),
  ('d3c4b5a6-e7f8-5b9c-0d1e-2f3a4b5c6d7e', 'Physics', 'Dynamics', 'A 5 kg object is pushed with a net force of 20 N. Its acceleration is:', '100 m/s²', '4 m/s²', '0.25 m/s²', '25 m/s²', 'B', 'From F = ma, a = F/m = 20/5 = 4 m/s².', 'easy'),
  ('e4d5c6b7-f8a9-5c0d-1e2f-3a4b5c6d7e8f', 'Physics', 'Work and Energy', 'A spring is compressed by 0.1 m from its natural length. If the spring constant is 500 N/m, the elastic potential energy stored is:', '0.5 J', '5 J', '2.5 J', '50 J', 'C', 'Elastic PE = ½kx² = ½(500)(0.1²) = ½(500)(0.01) = 2.5 J.', 'medium'),
  ('f5e6d7c8-a9b0-5d1e-2f3a-4b5c6d7e8f9a', 'Physics', 'Fluid Dynamics', 'The pressure at the bottom of a beaker filled with water (ρ = 1000 kg/m³) to a depth of 20 cm (g = 10 m/s²) is approximately:', '200 Pa', '2000 Pa', '20 Pa', '20000 Pa', 'B', 'P = ρgh = 1000 × 10 × 0.20 = 2000 Pa.', 'medium'),
  ('a6f7e8d9-b0c1-5e2f-3a4b-5c6d7e8f9a0b', 'Physics', 'Fluid Dynamics', 'The principle of continuity for an incompressible fluid states that:', 'Pressure decreases with speed', 'Volume is conserved', 'The product of cross-sectional area and velocity is constant', 'Density increases with depth', 'C', 'For an incompressible fluid, A₁v₁ = A₂v₂ — the flow rate is constant throughout a pipe of varying cross-section.', 'medium'),
  ('b7a8f9e0-c1d2-5f3a-4b5c-6d7e8f9a0b1c', 'Physics', 'Fluid Dynamics', 'According to Bernoulli''s principle, as the speed of a fluid increases, its:', 'Temperature increases', 'Density increases', 'Viscosity increases', 'Pressure decreases', 'D', 'Bernoulli''s principle: where fluid speed increases, pressure decreases (and vice versa), for steady, incompressible, non-viscous flow.', 'medium'),
  ('c8b9a0f1-d2e3-5a4b-5c6d-7e8f9a0b1c2d', 'Physics', 'Fluid Dynamics', 'The SI unit of viscosity is:', 'Pascal', 'Poise', 'Pa·s', 'N/m', 'C', 'Dynamic viscosity is measured in pascal-seconds (Pa·s). Poise is the CGS unit.', 'hard'),
  ('d9c0b1a2-e3f4-5b5c-6d7e-8f9a0b1c2d3e', 'Physics', 'Fluid Dynamics', 'A hollow iron ball floats in water. If the iron were melted and recast as a solid ball of the same mass, it would:', 'Float at the same level', 'Float higher', 'Sink', 'Float lower', 'C', 'The hollow ball displaces more water per unit mass. When recast as solid, its volume decreases, density increases above water, and it sinks.', 'hard'),
  ('e0d1c2b3-f4a5-5c6d-7e8f-9a0b1c2d3e4f', 'Physics', 'Oscillations and Waves', 'A simple pendulum of length 1 m on a planet where g = 4 m/s² has a period of approximately:', '3.14 s', '1.0 s', '2.0 s', '0.5 s', 'A', 'T = 2π√(L/g) = 2π√(1/4) = 2π(0.5) = π ≈ 3.14 s.', 'medium'),
  ('f1e2d3c4-a5b6-5d7e-8f9a-0b1c2d3e4f5a', 'Physics', 'Oscillations and Waves', 'The frequency of a simple pendulum does NOT depend on:', 'Length of the pendulum', 'Acceleration due to gravity', 'Mass of the bob', 'The gravitational field strength', 'C', 'T = 2π√(L/g) — frequency depends on L and g, but not on the mass of the bob.', 'medium'),
  ('a2f3e4d5-b6c7-5e8f-9a0b-1c2d3e4f5a6b', 'Physics', 'Oscillations and Waves', 'A transverse wave on a string has amplitude 4 cm and wavelength 2 m. If the wave speed is 10 m/s, its frequency is:', '20 Hz', '5 Hz', '0.05 Hz', '2.5 Hz', 'B', 'f = v/λ = 10/2 = 5 Hz.', 'medium'),
  ('b3a4f5e6-c7d8-5f9a-0b1c-2d3e4f5a6b7c', 'Physics', 'Oscillations and Waves', 'When a wave reflects off a fixed end, it undergoes a phase change of:', '0°', '90°', '180°', '270°', 'C', 'Reflection at a fixed (rigid) boundary inverts the wave — a 180° (π rad) phase shift.', 'medium'),
  ('c4b5a6f7-d8e9-5a0b-1c2d-3e4f5a6b7c8d', 'Physics', 'Oscillations and Waves', 'A tuning fork of frequency 256 Hz produces sound in air (speed 340 m/s). The wavelength is:', '1.33 m', '0.75 m', '1.33 cm', '75 m', 'A', 'λ = v/f = 340/256 ≈ 1.33 m.', 'medium'),
  ('d5c6b7a8-e9f0-5b1c-2d3e-4f5a6b7c8d9e', 'Physics', 'Light and Optics', 'A ray of light passes from air (n = 1) into glass (n = 1.5). The angle of refraction is:', 'Greater than the angle of incidence', 'Equal to the angle of incidence', 'Less than the angle of incidence', '90°', 'C', 'Light bends toward the normal when entering a denser medium (n₂ > n₁), so the angle of refraction is smaller.', 'medium'),
  ('e6d7c8b9-f0a1-5c2d-3e4f-5a6b7c8d9e0f', 'Physics', 'Light and Optics', 'The critical angle for total internal reflection is given by:', 'sin θ_c = n₁/n₂', 'sin θ_c = n₂/n₁', 'tan θ_c = n₁/n₂', 'cos θ_c = n₂/n₁', 'B', 'Total internal reflection occurs when light goes from a denser to a less dense medium: sin θ_c = n₂/n₁ (where n₁ > n₂).', 'hard'),
  ('f7e8d9c0-a1b2-5d3e-4f5a-6b7c8d9e0f1a', 'Physics', 'Heat and Thermodynamics', 'The specific heat capacity of water is 4200 J/(kg·K). The energy needed to raise 2 kg of water by 50°C is:', '420 kJ', '210 kJ', '420 J', '840 kJ', 'A', 'Q = mcΔT = 2 × 4200 × 50 = 420,000 J = 420 kJ.', 'medium'),
  ('a8f9e0d1-b2c3-5e4f-5a6b-7c8d9e0f1a2b', 'Physics', 'Heat and Thermodynamics', 'During a phase change (e.g. ice melting to water at 0°C), the temperature:', 'Rises steadily', 'Drops', 'Stays constant', 'Fluctuates', 'C', 'During a phase transition, all added heat goes into breaking bonds (latent heat) rather than raising temperature.', 'medium'),
  ('b9a0f1e2-c3d4-5f5a-6b7c-8d9e0f1a2b3c', 'Physics', 'Heat and Thermodynamics', 'The latent heat of fusion is the heat required to:', 'Raise the temperature of a substance by 1°C', 'Convert a liquid to gas at constant temperature', 'Convert a solid to liquid at constant temperature', 'Cool a gas to its boiling point', 'C', 'Latent heat of fusion = energy to melt (solid → liquid) at constant temperature. Latent heat of vaporisation is for liquid → gas.', 'medium'),
  ('c0b1a2f3-d4e5-5a6b-7c8d-9e0f1a2b3c4d', 'Physics', 'Heat and Thermodynamics', 'Two metal bars of equal length and cross-section, one copper (k = 400 W/m·K) and one steel (k = 50 W/m·K), conduct heat. Which conducts heat faster?', 'Steel', 'Both conduct at the same rate', 'Copper', 'Neither conducts heat', 'C', 'Higher thermal conductivity (k) means faster heat conduction. Copper (k = 400) conducts 8× faster than steel (k = 50).', 'easy'),
  ('d1c2b3a4-e5f6-5b7c-8d9e-0f1a2b3c4d5e', 'Physics', 'Electricity and Magnetism', 'A wire of resistance R is cut into two equal halves. The resistance of each half is:', 'R', 'R/2', '2R', 'R/4', 'B', 'Resistance R = ρL/A. Halving the length halves the resistance: each half has resistance R/2.', 'medium'),
  ('e2d3c4b5-f6a7-5c8d-9e0f-1a2b3c4d5e6f', 'Physics', 'Electricity and Magnetism', 'In a parallel combination of two resistors R₁ and R₂, the equivalent resistance is:', 'R₁ + R₂', 'R₁ × R₂', '(R₁ × R₂)/(R₁ + R₂)', '1/(R₁ + R₂)', 'C', 'For two resistors in parallel: 1/R_eq = 1/R₁ + 1/R₂, giving R_eq = (R₁R₂)/(R₁ + R₂).', 'medium'),
  ('f3e4d5c6-a7b8-5d9e-0f1a-2b3c4d5e6f7a', 'Physics', 'Electricity and Magnetism', 'The energy stored in a charged capacitor is:', 'QV', '½QV', 'Q²V', '2QV', 'B', 'Energy stored in a capacitor = ½QV = ½CV² = Q²/(2C).', 'medium'),
  ('a4f5e6d7-b8c9-5e0f-1a2b-3c4d5e6f7a8b', 'Physics', 'Magnetism', 'The magnetic field inside a solenoid is:', 'Non-uniform', 'Zero', 'Uniform and parallel to the axis', 'Circular', 'C', 'Inside a long solenoid, the magnetic field is uniform, parallel to the axis, and given by B = μ₀nI.', 'medium'),
  ('b5a6f7e8-c9d0-5f1a-2b3c-4d5e6f7a8b9c', 'Physics', 'Modern Physics', 'De Broglie''s hypothesis states that a moving particle has an associated:', 'Magnetic field', 'Wavelength', 'Electric charge', 'Nuclear force', 'B', 'De Broglie wavelength λ = h/(mv) — every moving particle exhibits wave-like properties.', 'medium'),
  ('c6b7a8f9-d0e1-5a2b-3c4d-5e6f7a8b9c0d', 'Physics', 'Modern Physics', 'The mass-energy equivalence relation is:', 'E = mc', 'E = mc²', 'E = m/c²', 'E = m²c', 'B', 'Einstein''s relation: E = mc² — mass and energy are equivalent; a small mass corresponds to enormous energy.', 'easy'),
  ('d7c8b9a0-e1f2-5b3c-4d5e-6f7a8b9c0d1e', 'Physics', 'Modern Physics', 'In the Bohr model of the hydrogen atom, electrons can only exist in:', 'Any orbit at any energy', 'Fixed orbits with quantised energy levels', 'The nucleus', 'Random orbits', 'B', 'Bohr''s model: electrons occupy fixed orbits with quantised energies; they jump between orbits by absorbing or emitting photons of specific energy.', 'medium'),
  ('e8d9c0b1-f2a3-5c4d-5e6f-7a8b9c0d1e2f', 'Physics', 'Modern Physics', 'Gamma rays are:', 'High-energy electrons', 'High-energy electromagnetic radiation from the nucleus', 'Charged particles', 'Slow-moving neutrons', 'B', 'Gamma rays are high-energy photons (EM radiation) emitted during nuclear transitions — they have the shortest wavelength in the EM spectrum.', 'easy'),
  ('f9e0d1c2-a3b4-5d5e-6f7a-8b9c0d1e2f3a', 'Physics', 'Solid State', 'Hooke''s law states that within the elastic limit:', 'Stress is proportional to strain', 'Strain is proportional to stress squared', 'Force is inversely proportional to extension', 'Extension is independent of force', 'A', 'Hooke''s law: F = kx or stress = Young''s modulus × strain, valid within the elastic limit.', 'medium'),
  ('a0f1e2d3-b4c5-5e6f-7a8b-9c0d1e2f3a4b', 'Physics', 'Solid State', 'The Young''s modulus of a wire is defined as:', 'Stress × strain', 'Strain / stress', 'Stress / strain', 'Force / area²', 'C', 'Young''s modulus Y = stress/strain = (F/A)/(ΔL/L). It measures the stiffness of a material.', 'medium'),
  ('b1a0f2e3-c5d6-5f7a-8b9c-0d1e2f3a4b5c', 'Physics', 'Solid State', 'A wire of original length 2 m extends by 0.5 mm when a load is applied. The strain is:', '2.5 × 10⁻⁴', '4 × 10⁻³', '0.25', '4', 'A', 'Strain = ΔL/L = 0.5 × 10⁻³ m / 2 m = 2.5 × 10⁻⁴.', 'medium'),
  ('c2b1a0f3-d6e7-5a8b-9c0d-1e2f3a4b5c6d', 'Physics', 'Solid State', 'The elastic limit of a material is:', 'The maximum stress a material can withstand before breaking', 'The maximum stress up to which the material returns to its original shape', 'The stress at which the material becomes liquid', 'The stress at which the material starts to melt', 'B', 'The elastic limit is the maximum stress/strain beyond which the material does not return to its original shape (permanent deformation occurs).', 'medium'),
  ('d3c2b1a0-e7f8-5b9c-0d1e-2f3a4b5c6d7e', 'Physics', 'Solid State', 'A steel wire of cross-sectional area 2 × 10⁻⁶ m² is stretched by a force of 100 N. The stress in the wire is:', '5 × 10⁷ Pa', '2 × 10⁻⁴ Pa', '100 Pa', '5 × 10⁻⁸ Pa', 'A', 'Stress = F/A = 100 / (2 × 10⁻⁶) = 5 × 10⁷ Pa.', 'medium'),
  ('e4d3c2b1-f8a9-5c0d-1e2f-3a4b5c6d7e8f', 'Physics', 'Electromagnetic Waves', 'Which of the following is an electromagnetic wave?', 'Sound wave', 'Water wave', 'X-ray', 'Seismic wave', 'C', 'X-rays are electromagnetic waves. Sound, water, and seismic waves are mechanical waves requiring a medium.', 'easy'),
  ('f5e4d3c2-a9b0-5d1e-2f3a-4b5c6d7e8f9a', 'Physics', 'Electromagnetic Waves', 'The electromagnetic spectrum in order of increasing frequency is:', 'Gamma rays, X-rays, UV, visible, IR, microwaves, radio waves', 'Radio waves, microwaves, IR, visible, UV, X-rays, gamma rays', 'Visible, UV, X-rays, gamma rays, radio waves, microwaves, IR', 'Microwaves, radio waves, IR, visible, UV, X-rays, gamma rays', 'B', 'Radio waves have the longest wavelength/lowest frequency; gamma rays have the shortest wavelength/highest frequency.', 'easy'),
  ('a6f5e4d3-b0c1-5e2f-3a4b-5c6d7e8f9a0b', 'Physics', 'Electromagnetic Waves', 'Microwaves are used in:', 'X-ray imaging', 'Cooking food', 'Night vision', 'Sterilising wounds', 'B', 'Microwaves are used in microwave ovens to heat food by exciting water molecules. UV is used for sterilisation; IR for night vision.', 'easy'),
  ('b7a6f5e4-c1d2-5f3a-4b5c-6d7e8f9a0b1c', 'Physics', 'Simple Harmonic Motion', 'A body executing SHM has maximum velocity at:', 'The extreme positions', 'The mean (equilibrium) position', 'Halfway between mean and extreme', 'At any point', 'B', 'In SHM, velocity is maximum at the equilibrium position (where all potential energy converts to kinetic energy) and zero at extremes.', 'medium'),
  ('c8b7a6f5-d2e3-5a4b-5c6d-7e8f9a0b1c2d', 'Physics', 'Simple Harmonic Motion', 'A mass-spring system has mass 0.5 kg and spring constant 200 N/m. Its angular frequency is:', '100 rad/s', '400 rad/s', '20 rad/s', '40 rad/s', 'C', 'ω = √(k/m) = √(200/0.5) = √400 = 20 rad/s.', 'medium'),
  ('d9c8b7a6-e3f4-5b5c-6d7e-8f9a0b1c2d3e', 'Physics', 'Simple Harmonic Motion', 'The total energy of a simple harmonic oscillator is:', 'Proportional to the amplitude', 'Proportional to the square of the amplitude', 'Zero at the mean position', 'Maximum at the extreme positions', 'B', 'Total energy E = ½kA² — proportional to the square of amplitude. Energy is constant; KE is max at mean, PE is max at extremes.', 'medium'),
  ('e0d9c8b7-f4a5-5c6d-7e8f-9a0b1c2d3e4f', 'Physics', 'Simple Harmonic Motion', 'The period of a simple pendulum of length L on Earth is T. If L is quadrupled, the new period is:', 'T', '2T', '4T', 'T/2', 'B', 'T = 2π√(L/g). If L → 4L, then T → 2π√(4L/g) = 2 × 2π√(L/g) = 2T.', 'medium'),
  ('f1a2b3c4-d5e6-5f7a-8b9c-0d1e2f3a4b5c', 'Physics', 'Fluid Dynamics', 'An object weighs 10 N in air and 8 N when fully submerged in water. The buoyant force on it is:', '2 N', '8 N', '10 N', '18 N', 'A', 'Buoyant force = weight in air − apparent weight in water = 10 − 8 = 2 N.', 'easy'),
  ('a2b3c4d5-e6f7-5a8b-9c0d-1e2f3a4b5c6d', 'Physics', 'Oscillations and Waves', 'A standing wave on a string fixed at both ends has 3 nodes (including the ends) and 2 antinodes. It is the:', 'First harmonic', 'Second harmonic', 'Third harmonic', 'Fourth harmonic', 'B', 'Two antinodes (half-wavelengths) on a string fixed at both ends correspond to the second harmonic (n = 2).', 'hard'),
  ('b3c4d5e6-f7a8-5b9c-0d1e-2f3a4b5c6d7e', 'Physics', 'Heat and Thermodynamics', 'The efficiency of a Carnot engine operating between 500 K and 300 K is:', '40%', '60%', '50%', '75%', 'A', 'Carnot efficiency η = 1 − T_cold/T_hot = 1 − 300/500 = 1 − 0.6 = 0.4 = 40%.', 'medium'),
  ('c4d5e6f7-a8b9-5c0d-1e2f-3a4b5c6d7e8f', 'Physics', 'Modern Physics', 'The work function of a metal is 2.0 eV. The threshold frequency of incident light is approximately:', '4.8 × 10¹⁴ Hz', '2.0 × 10¹⁴ Hz', '6.0 × 10¹⁴ Hz', '3.0 × 10¹⁴ Hz', 'A', 'E = hf → f = E/h = (2.0 × 1.6 × 10⁻¹⁹) / (6.63 × 10⁻³⁴) ≈ 4.8 × 10¹⁴ Hz.', 'hard'),
  ('d5e6f7a8-b9c0-5d1e-2f3a-4b5c6d7e8f9a', 'Physics', 'Solid State', 'A rubber band is stretched and released. It returns to its original shape because:', 'Friction is negligible', 'It was within its elastic limit', 'It was stretched slowly', 'The force was very small', 'B', 'The rubber band returns to its original shape because the deformation was within its elastic limit.', 'easy'),
  ('e6f7a8b9-c0d1-5e2f-3a4b-5c6d7e8f9a0b', 'Physics', 'Electromagnetic Waves', 'Ultraviolet light can cause:', 'Cooking of food', 'Sunburn on skin', 'Heating of a microwave oven', 'Night vision', 'B', 'UV radiation has enough energy to damage skin cells, causing sunburn. IR causes heating; microwaves cook food.', 'easy'),
  ('f7a8b9c0-d1e2-5f3a-4b5c-6d7e8f9a0b1c', 'Physics', 'Simple Harmonic Motion', 'The displacement of an SHM oscillator is given by x = 0.05 sin(10πt) m. Its amplitude is:', '10π m', '0.05 cm', '0.05 m', '5 m', 'C', 'Comparing with x = A sin(ωt), the amplitude A = 0.05 m (5 cm).', 'medium'),
  ('a8b9c0d1-e2f3-5a4b-5c6d-7e8f9a0b1c2d', 'Physics', 'Measurement', 'A micrometer screw gauge has a least count of 0.01 mm. If the thimble reading is 45 and the main scale reading is 3.5 mm, the total reading is:', '3.50 mm', '3.95 mm', '3.45 mm', '4.50 mm', 'B', 'Total reading = main scale + (thimble × LC) = 3.5 + (45 × 0.01) = 3.5 + 0.45 = 3.95 mm.', 'medium'),
  ('b9c0d1e2-f3a4-5b5c-6d7e-8f9a0b1c2d3e', 'Physics', 'Dynamics', 'Two objects of masses 2 kg and 3 kg are connected by a light inextensible string over a frictionless pulley. The acceleration of the system (g = 10 m/s²) is:', '2 m/s²', '5 m/s²', '10 m/s²', '1 m/s²', 'A', 'a = (m₂ − m₁)g/(m₁ + m₂) = (3 − 2)(10)/(2 + 3) = 10/5 = 2 m/s².', 'medium'),
  ('c0d1e2f3-a4b5-5c6d-7e8f-9a0b1c2d3e4f', 'Physics', 'Light and Optics', 'In Young''s double slit experiment, increasing the slit separation causes the fringe width to:', 'Increase', 'Decrease', 'Stay the same', 'Become infinite', 'B', 'Fringe width β = λD/d. Increasing slit separation d decreases fringe width.', 'medium'),
  ('649ec700-c480-5c21-bd33-df6735fbd36c', 'English', 'Grammar', 'Choose the correct form: "She ___ to school every day."', 'going', 'go', 'gone', 'goes', 'D', 'Third-person singular present simple takes the verb with –s: she goes.', 'easy'),
  ('e757f85b-5711-59c2-9d41-1117a204e520', 'English', 'Grammar', 'Choose the correct sentence:', 'He don''t like tea', 'He doesn''t like tea', 'He don''t likes tea', 'He not like tea', 'B', 'With “he” (third person singular), the negative auxiliary is “doesn’t” + base verb: doesn’t like.', 'easy'),
  ('ddc76134-6a71-57ea-999e-4ac5b5f546eb', 'English', 'Grammar', 'The past tense of "buy" is:', 'buyed', 'bought', 'baught', 'buys', 'B', '“Buy” is irregular: buy – bought – bought.', 'easy'),
  ('fe0f2995-f4cc-5293-8464-d9356dac6072', 'English', 'Grammar', 'Select the passive form of: "The teacher praised the student."', 'The student was praised by the teacher', 'The student were praised by the teacher', 'The teacher was praised by the student', 'The student is praised by the teacher', 'A', 'Active → passive: the object becomes the subject; be + past participle; “by” + agent. Praised → was praised.', 'medium'),
  ('593cf92d-3318-52b0-86aa-4bfab0565141', 'English', 'Grammar', 'Choose the correct relative pronoun: "This is the book ___ I was telling you about."', 'who', 'which', 'whom', 'whose', 'B', '“Which” refers to things (the book); “who/whom” refer to people; “whose” shows possession.', 'medium'),
  ('fb76045d-dc2c-5626-a011-b0b68448f4c3', 'English', 'Grammar', 'Identify the sentence with correct subject–verb agreement:', 'The list of items are on the table', 'The list of items were on the table', 'The list of items were going', 'The list of items is on the table', 'D', 'The subject “list” is singular, so the verb is singular: is. “of items” is a prepositional phrase.', 'hard'),
  ('50bb9e43-7eee-5aaa-8f9a-e6ff9e3b8193', 'English', 'Grammar', 'Choose the correctly spelled word:', 'Receeve', 'Recieve', 'Receive', 'Receeiv', 'C', 'The correct spelling is “receive” (“i before e except after c”).', 'easy'),
  ('72799e84-2779-5461-b2b3-0bb01f5d21de', 'English', 'Grammar', 'Choose the correct conditional: "If it ___ tomorrow, we will stay home."', 'will rain', 'rained', 'rain', 'rains', 'D', 'First conditional: if + present simple, will + base verb. If it rains… we will stay.', 'medium'),
  ('2ca9b8c6-288c-55e3-ab02-fe0f1e1810fe', 'English', 'Grammar', 'Choose the correct article: "She is ___ honest girl."', 'a', 'no article', 'an', 'the', 'C', 'Use “an” before vowel sounds; “honest” begins with a vowel sound (silent h), so “an honest girl.”', 'hard'),
  ('c2120ea4-dafa-5e66-b3b2-3cb0b4bc8080', 'English', 'Grammar', 'The plural of "child" is:', 'childen', 'childs', 'childes', 'children', 'D', '“Child” is an irregular noun; its plural is “children.”', 'easy'),
  ('d8a9c927-29cf-5e91-9c78-6b301bbf2989', 'English', 'Grammar', 'Choose the adverb in: "She sings beautifully."', 'sings', 'sings beautifully', 'beautifully', 'She', 'C', '“Beautifully” describes how she sings and ends in –ly — it is an adverb.', 'easy'),
  ('ecda9420-76f1-5ceb-a9f1-3616a028130d', 'English', 'Grammar', 'Choose the correct indirect speech: He said, "I am tired."', 'He says that he were tired', 'He said that he is tired', 'He said that he was tired', 'He said that he is being tired', 'C', 'With a past reporting verb (said), the tense shifts back: am → was. He said that he was tired.', 'medium'),
  ('021aa20e-67b3-5046-b629-5c36eca333e9', 'English', 'Grammar', 'Identify the preposition: "The cat is sitting ___ the table."', 'cat', 'table', 'under', 'sitting', 'C', '“Under” is a preposition showing position relative to the table.', 'easy'),
  ('94d3dc1c-fa19-539f-bf2d-aa59848bc569', 'English', 'Grammar', 'Choose the correct form: "She has ___ her homework."', 'completing', 'completed', 'complete', 'completes', 'B', 'Present perfect uses have/has + past participle: has completed.', 'easy'),
  ('fdd06055-c472-5dd0-8ff5-df61feda4d34', 'English', 'Grammar', 'Which sentence is punctuated correctly?', 'What is your name.', 'What''s your name?', 'Whats your name?', 'Whats your name,', 'B', '“What’s” needs the apostrophe for “what is,” and a question ends with a question mark.', 'easy'),
  ('72e68104-2d0c-5837-aa33-f93e1db6c5c3', 'English', 'Vocabulary', 'Choose the synonym of "abundant":', 'plentiful', 'scarce', 'empty', 'rare', 'A', '“Abundant” means plentiful; scarce and rare are its opposites.', 'easy'),
  ('f0c9f55d-5e9e-5fea-bc69-aec03a3fe4ea', 'English', 'Vocabulary', 'Choose the synonym of "generous":', 'stingy', 'selfish', 'greedy', 'liberal and giving', 'D', '“Generous” means giving freely; stingy is its antonym.', 'easy'),
  ('61e5139a-6e07-5687-87ac-61d1e86ee2fb', 'English', 'Vocabulary', 'Choose the antonym of "brave":', 'bold', 'cowardly', 'fearless', 'courageous', 'B', '“Brave” = courageous; cowardly is its opposite.', 'easy'),
  ('9c2ba89d-aa34-58d7-93dc-b7346adcc07b', 'English', 'Vocabulary', 'Choose the synonym of "obvious":', 'doubtful', 'vague', 'hidden', 'clear and evident', 'D', '“Obvious” means clearly evident; hidden, doubtful and vague are opposites.', 'easy'),
  ('e878c517-be38-592d-bf1a-96c6c5edba53', 'English', 'Vocabulary', 'Choose the antonym of "ancient":', 'archaic', 'antique', 'old', 'modern', 'D', '“Ancient” means very old; the antonym is modern or contemporary.', 'easy'),
  ('32525401-eb4b-5d6e-bcb7-7e80d7dbb3dd', 'English', 'Vocabulary', 'The word "physician" is closest in meaning to:', 'chemist', 'doctor', 'pharmacist', 'physicist', 'B', 'A physician is a medical doctor. A physicist studies physics; a pharmacist dispenses medicines.', 'medium'),
  ('52a60d17-2f71-5df2-8337-396134eb627f', 'English', 'Vocabulary', 'Choose the correctly spelled word: "The doctor explained the ___ effects of the drug."', 'side', 'sigh', 'sighed', 'sid', 'A', 'The correct spelling is “side effects.” (“sigh” is a breath.)', 'easy'),
  ('e9000210-ae09-5602-89ac-8c7fca99f62d', 'English', 'Vocabulary', 'Choose the synonym of "rapid":', 'slow', 'fast', 'hesitant', 'gentle', 'B', '“Rapid” means fast/quick; slow is its opposite.', 'easy'),
  ('66949d06-c80b-5510-9b90-cd6edc60c68d', 'English', 'Vocabulary', 'Choose the antonym of "victory":', 'achievement', 'success', 'defeat', 'triumph', 'C', '“Victory” means winning; defeat is its opposite.', 'medium'),
  ('6d1a03e0-290e-5b14-837f-6a2dd3ad9626', 'English', 'Sentence Completion', 'Complete: "The patient was told to take the medicine on an ___ stomach."', 'active', 'early', 'empty', 'absent', 'C', 'The fixed phrase is “on an empty stomach” — before eating.', 'medium'),
  ('c3fe1416-eb60-51bc-a0ee-c8aaaf6f95f1', 'English', 'Sentence Completion', 'Complete: "Hard work is the key ___ success."', 'from', 'for', 'of', 'to', 'D', 'The fixed expression is “the key to success.”', 'medium'),
  ('811c02c1-8ecb-5b27-8637-c34d3dbaae03', 'English', 'Sentence Completion', 'Complete: "He succeeded ___ passing the exam."', 'in', 'at', 'for', 'on', 'A', '“Succeed in + gerund”: He succeeded in passing the exam.', 'medium'),
  ('3132df3b-7a22-5e5d-8dc5-ff323a51cbf0', 'English', 'Sentence Completion', 'Choose the best option: "Despite the rain, the match ___."', 'has been continue', 'continued', 'was continued', 'was continue', 'B', '“Despite” + noun; “continue” is intransitive, so: the match continued.', 'hard'),
  ('d6e72f71-c905-5f0d-a0f3-e5552077ba92', 'English', 'Sentence Completion', 'Complete: "Neither the student nor his parents ___ aware of the result."', 'was', 'has been', 'is being', 'were', 'D', 'With “neither…nor,” the verb agrees with the nearer subject (“parents,” plural) → were.', 'hard'),
  ('62775cfe-d940-56bc-9612-35d5a299cd16', 'English', 'Comprehension', 'The main idea of a short paragraph is usually stated in the:', 'Topic (first) sentence', 'Middle punctuation', 'Last word only', 'Title absent from the text', 'A', 'A paragraph’s topic sentence, usually the first, states the main idea that the rest supports.', 'medium'),
  ('638cddb3-ee99-52af-a31b-c34dae8ba762', 'English', 'Grammar', 'Choose the correct tense: "By next year, she ___ her MDCAT."', 'takes', 'is taken', 'take', 'will have taken', 'D', 'Future perfect (by + future time): will have taken.', 'medium'),
  ('8da3feaf-81ea-5f10-8394-21fbae5b8f2b', 'English', 'Grammar', 'Choose the correct phrase: "I look forward ___ hearing from you."', 'with', 'for', 'at', 'to', 'D', 'The idiom is “look forward to + -ing.”', 'medium'),
  ('fb69007d-460b-54da-a575-3bd3a525088c', 'English', 'Grammar', 'Choose the correctly punctuated sentence:', 'The doctor, who is very kind, helped the patient', 'The doctor who is very kind, helped the patient', 'The doctor, who is very kind helped the patient', 'The doctor who is very kind helped, the patient', 'A', 'A non-restrictive relative clause is set off by commas on both sides.', 'hard'),
  ('ee081285-0ca3-51bb-82e9-0dc5c0443c8b', 'English', 'Vocabulary', 'Choose the word closest in meaning to "diligent":', 'hardworking', 'lazy', 'careless', 'ignorant', 'A', '“Diligent” means careful and hardworking; lazy and careless are opposites.', 'easy'),
  ('5fe42872-abf4-501d-b36e-f6343a2a1060', 'English', 'Vocabulary', 'The antonym of "artificial" is:', 'natural', 'pretend', 'synthetic', 'man-made', 'A', '“Artificial” means not natural, made by humans; the antonym is natural.', 'easy'),
  ('4dd7a8c8-7d56-5bf1-8762-808f93baa2bb', 'English', 'Sentence Completion', 'Complete: "Prevention is better than ___."', 'cure', 'medication only', 'treatment delays', 'care health', 'A', 'The proverb is “Prevention is better than cure.”', 'easy'),
  ('b4369bdc-c785-52e4-b93e-4d442b726ab0', 'English', 'Sentence Completion', 'Complete: "The old man was too weak ___."', 'to walk', 'for walk', 'walking he', 'that he walk', 'A', '“Too + adjective + to + verb”: too weak to walk.', 'medium'),
  ('9cab6e96-62e7-5545-a697-6856354f26a7', 'English', 'Grammar', 'Choose the correct article: "He is looking for ___ job."', 'a', 'no article', 'an', 'the', 'A', '“Job” begins with a consonant sound and is non-specific here, so use “a”.', 'medium'),
  ('02af198d-2cbb-5feb-ba61-2010703acd9e', 'English', 'Vocabulary', 'Choose the synonym of "essential":', 'unimportant', 'necessary', 'minor', 'optional', 'B', '“Essential” means absolutely necessary; optional and unimportant are opposites.', 'easy'),
  ('0fd858ac-5219-5fbf-b764-aa3153d37f2f', 'English', 'Grammar', 'Choose the correct form: "Neither of the two answers ___ correct."', 'are', 'were', 'is', 'have been', 'C', '“Neither” is singular and takes a singular verb: is.', 'hard'),
  ('b46bbb96-4730-5177-88ad-b47ac4b0b9fa', 'English', 'Vocabulary', 'Choose the antonym of "permanent":', 'temporary', 'lasting', 'stable', 'everlasting', 'A', '"Permanent" means lasting; "temporary" means for a limited time — its opposite.', 'easy'),
  ('a1b2c3d4-e5f6-7a8b-9c0d-1e2f3a4b5c6d', 'English', 'Vocabulary', 'Choose the synonym of "benevolent":', 'kind', 'cruel', 'selfish', 'hostile', 'A', '"Benevolent" means well-meaning and kind; cruel and hostile are antonyms.', 'medium'),
  ('b2c3d4e5-f6a7-8b9c-0d1e-2f3a4b5c6d7e', 'English', 'Vocabulary', 'Choose the antonym of "eloquent":', 'articulate', 'fluent', 'inarticulate', 'persuasive', 'C', '"Eloquent" means fluent and persuasive; inarticulate is the opposite.', 'medium'),
  ('c3d4e5f6-a7b8-9c0d-1e2f-3a4b5c6d7e8f', 'English', 'Vocabulary', 'Choose the word closest in meaning to "lethargic":', 'energetic', 'sluggish', 'enthusiastic', 'alert', 'B', '"Lethargic" means sluggish and lacking energy; energetic is the antonym.', 'medium'),
  ('d4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f90', 'English', 'Vocabulary', 'Choose the antonym of "verbose":', 'wordy', 'concise', 'lengthy', 'talkative', 'B', '"Verbose" means using more words than needed; concise is the opposite.', 'medium'),
  ('e5f6a7b8-c9d0-1e2f-3a4b-5c6d7e8f9012', 'English', 'Vocabulary', 'Choose the synonym of "resilient":', 'fragile', 'tough', 'weak', 'sensitive', 'B', '"Resilient" means able to recover quickly; tough and durable are synonyms.', 'medium'),
  ('f6a7b8c9-d0e1-2f3a-4b5c-6d7e8f901234', 'English', 'Vocabulary', 'Choose the antonym of "abundant":', 'plentiful', 'adequate', 'scarce', 'ample', 'C', '"Abundant" means plentiful or ample; scarce means insufficient — its opposite.', 'medium'),
  ('1a2b3c4d-5e6f-7081-92a3-b4c5d6e7f809', 'English', 'Vocabulary', 'Choose the synonym of "precarious":', 'stable', 'dangerous', 'secure', 'safe', 'B', '"Precarious" means dangerously unstable; dangerous captures its meaning.', 'medium'),
  ('2b3c4d5e-6f70-8192-a3b4-c5d6e7f80912', 'English', 'Vocabulary', 'Choose the antonym of "meticulous":', 'thorough', 'careful', 'careless', 'precise', 'C', '"Meticulous" means showing great attention to detail; careless is the opposite.', 'medium'),
  ('3c4d5e6f-7081-92a3-b4c5-d6e7f8091234', 'English', 'Vocabulary', 'Choose the synonym of "ephemeral":', 'permanent', 'lasting', 'brief', 'eternal', 'C', '"Ephemeral" means short-lived or brief; permanent and eternal are antonyms.', 'medium'),
  ('4d5e6f70-8192-a3b4-c5d6-e7f809123456', 'English', 'Vocabulary', 'Choose the antonym of "adulterate":', 'contaminate', 'purify', 'degrade', 'corrupt', 'B', '"Adulterate" means to make impure; purify means to make clean — its opposite.', 'medium'),
  ('5e6f7081-92a3-b4c5-d6e7-f80912345678', 'English', 'Grammar', 'Choose the correct form: "They ___ dinner when the phone rang."', 'have cooked', 'were cooking', 'cooked', 'are cooking', 'B', 'Past continuous (were cooking) + past simple (rang) for an interrupted action.', 'medium'),
  ('6f708192-a3b4-c5d6-e7f8-091234567890', 'English', 'Grammar', 'Choose the correct subject–verb agreement: "Every student ___ a textbook."', 'have', 'having', 'has', 'are having', 'C', '"Every student" is singular; the verb must also be singular: has.', 'medium'),
  ('708192a3-b4c5-d6e7-f809-123456789012', 'English', 'Grammar', 'Choose the correct preposition: "She is fond ___ music."', 'in', 'on', 'at', 'of', 'D', 'The fixed prepositional phrase is "fond of something."', 'medium'),
  ('8192a3b4-c5d6-e7f8-0912-345678901234', 'English', 'Grammar', 'Choose the correct article: "He is ___ university student."', 'a', 'an', 'the', 'no article', 'A', '"University" starts with a consonant sound (/juː/), so use "a", not "an".', 'medium'),
  ('92a3b4c5-d6e7-f809-1234-567890123456', 'English', 'Grammar', 'Choose the correct tense: "She ___ in Lahore since 2019."', 'lives', 'is living', 'has lived', 'have lived', 'C', 'Present perfect (has lived) is used with "since" to indicate an action that started in the past and continues.', 'medium'),
  ('a3b4c5d6-e7f8-0912-3456-789012345678', 'English', 'Grammar', 'Choose the correct form: "The news ___ shocking."', 'were', 'are', 'is', 'have been', 'C', '"News" is an uncountable noun and takes a singular verb: is.', 'medium'),
  ('b4c5d6e7-f809-1234-5678-901234567890', 'English', 'Grammar', 'Choose the correct form: "He made me ___ the truth."', 'to tell', 'telling', 'tells', 'tell', 'D', '"Make" takes a bare infinitive: made me tell (not "to tell").', 'medium'),
  ('c5d6e7f8-0912-3456-7890-123456789012', 'English', 'Grammar', 'Choose the correct preposition: "The meeting is ___ Monday."', 'in', 'on', 'at', 'by', 'B', 'Days of the week take the preposition "on": on Monday.', 'easy'),
  ('d6e7f809-1234-5678-9012-345678901234', 'English', 'Grammar', 'Choose the correct sentence:', 'Each of the boys have passed', 'Each of the boys has passed', 'Each of the boys have passing', 'Each of the boys are passed', 'B', '"Each" is singular and takes a singular verb: has passed.', 'medium'),
  ('e7f80912-3456-7890-1234-567890123456', 'English', 'Grammar', 'Choose the correct form: "If I ___ you, I would study harder."', 'am', 'was', 'were', 'be', 'C', 'Second conditional uses "were" for all subjects: If I were you…', 'medium'),
  ('f8091234-5678-9012-3456-789012345678', 'English', 'Grammar', 'Choose the correct article: "___ sun rises in the east."', 'A', 'An', 'The', 'No article', 'C', '"Sun" is a unique object; we use the definite article "the".', 'easy'),
  ('09123456-7890-1234-5678-901234567890', 'English', 'Grammar', 'Choose the correct form: "She would have passed if she ___ harder."', 'studied', 'had studied', 'has studied', 'studies', 'B', 'Third conditional: would have + past participle + if + past perfect (had studied).', 'hard'),
  ('12345678-90ab-cdef-1234-567890abcdef', 'English', 'Sentence Completion', 'Complete: "The doctor advised him to give ___ smoking."', 'out', 'up', 'off', 'in', 'B', 'The phrasal verb "give up" means to stop (a habit): give up smoking.', 'medium'),
  ('23456789-abcd-ef01-2345-6789abcdef01', 'English', 'Sentence Completion', 'Complete: "She is not only intelligent ___ also hardworking."', 'and', 'or', 'but', 'yet', 'C', 'The correlative conjunction pair is "not only … but also."', 'medium'),
  ('3456789a-bcde-f012-3456-789abcdef012', 'English', 'Sentence Completion', 'Complete: "As soon as the doctor arrived, the patient ___ better."', 'feels', 'felt', 'will feel', 'is feeling', 'B', '"As soon as" with past simple in the first clause triggers past simple in the second.', 'medium'),
  ('456789ab-cdef-0123-4567-89abcdef0123', 'English', 'Sentence Completion', 'Complete: "The nurse took ___ the patient''s temperature."', 'off', 'out', 'up', 'down', 'D', 'The phrasal verb "take down" means to record: took down the temperature.', 'medium'),
  ('56789abc-def0-1234-5678-9abcdef01234', 'English', 'Sentence Completion', 'Complete: "No sooner had she entered the room ___ the lights went off."', 'when', 'than', 'then', 'before', 'B', 'The correlative conjunction is "no sooner … than."', 'hard'),
  ('6789abcd-ef01-2345-6789-abcdef012345', 'English', 'Sentence Completion', 'Complete: "The patient was known ___ heart disease."', 'from', 'to', 'with', 'for', 'B', '"Known to suffer from" or "known to have" — "known to" is the correct preposition here.', 'medium'),
  ('789abcde-f012-3456-789a-bcdef0123456', 'English', 'Sentence Completion', 'Complete: "He insisted ___ going alone."', 'for', 'at', 'on', 'to', 'C', '"Insist on + gerund" is the correct idiomatic pattern.', 'medium'),
  ('89abcdef-0123-4567-89ab-cdef01234567', 'English', 'Sentence Completion', 'Complete: "Had I known the answer, I ___ you."', 'would tell', 'would have told', 'told', 'will tell', 'B', 'Third conditional inverted: Had I known … I would have told.', 'hard'),
  ('9abcdef0-1234-5678-9abc-def012345678', 'English', 'Sentence Completion', 'Complete: "It is time we ___ our seats."', 'take', 'took', 'taken', 'taking', 'B', '"It is time + subject + past simple" expresses that something should be done now.', 'hard'),
  ('abcdef01-2345-6789-abcd-ef0123456789', 'English', 'Sentence Completion', 'Complete: "The more you practice, the ___ you will become."', 'good', 'best', 'better', 'more good', 'C', 'The comparative correlative: "the more … the better."', 'medium'),
  ('bcdef012-3456-789a-bcde-f01234567890', 'English', 'Comprehension', 'Read: "Despite long hours of study, Ayesha failed the exam." What can be inferred?', 'Ayesha did not study at all', 'Studying alone does not guarantee success', 'The exam was unfair', 'Ayesha is not intelligent', 'B', '"Despite" signals a contrast — she studied hard yet failed, implying effort alone is not always enough.', 'medium'),
  ('cdef0123-4567-89ab-cdef-012345678901', 'English', 'Comprehension', 'Read: "The hospital was overcrowded, and the waiting list had grown to several months." What does this suggest?', 'The hospital is very popular', 'There is a shortage of healthcare resources', 'Patients enjoy waiting', 'The hospital has too many staff', 'B', 'Long waiting lists and overcrowding suggest inadequate resources relative to demand.', 'medium'),
  ('def01234-5678-9abc-def0-123456789012', 'English', 'Comprehension', 'Read: "Ali smiled politely but his eyes betrayed his frustration." What does "betrayed" mean here?', 'revealed unwillingly', 'lied about', 'bet on', 'agreed to', 'A', 'In context, "betrayed" means his eyes inadvertently revealed his true feelings of frustration.', 'medium'),
  ('ef012345-6789-abcd-ef01-234567890123', 'English', 'Comprehension', 'Read: "The medicine provided temporary relief, but the symptoms returned within hours." What is the tone of the passage?', 'Optimistic', 'Neutral', 'Frustrated and disappointed', 'Humorous', 'C', '"Temporary relief" followed by returning symptoms conveys disappointment and frustration.', 'medium'),
  ('f0123456-789a-bcde-f012-345678901234', 'English', 'Comprehension', 'Read: "Smoking cessation programs have proven effective, yet many smokers continue the habit." What is the author suggesting?', 'Cessation programs do not work', 'Smokers choose to ignore available help', 'All smokers will eventually quit', 'Smoking is harmless', 'B', '"Yet" shows contrast: programs exist and work, but smokers still do not use them — implying a choice or reluctance.', 'medium'),
  ('01234567-89ab-cdef-0123-456789abcdef', 'English', 'Comprehension', 'Read: "Regular exercise, combined with a balanced diet, is the cornerstone of preventive medicine." The word "cornerstone" most likely means:', 'minor detail', 'fundamental principle', 'optional suggestion', 'outdated concept', 'B', '"Cornerstone" metaphorically means the most essential or fundamental part.', 'medium'),
  ('12345678-9abc-def0-1234-56789abcdef0', 'English', 'Comprehension', 'Read: "The researcher spent years collecting data, only to find that her hypothesis was incorrect." What did the researcher most likely do next?', 'Published the results without checking', 'Revised her hypothesis based on the data', 'Ignored the data', 'Destroyed all her notes', 'B', 'A diligent researcher who discovers her hypothesis is wrong would revise it in light of the evidence.', 'medium'),
  ('51d0b04a-4f83-5f61-b1fe-c6688d495c67', 'English', 'Vocabulary', 'Pick the word closest in meaning to ''MELANCHOLY''.', 'Joyful', 'Pensive', 'Cheerful', 'Excited', 'B', 'Melancholy means a deep, thoughtful sadness — pensive and sorrowful; the opposite of joyful or cheerful.', 'medium'),
  ('84adce32-ee1c-5957-b1f4-442f3d169366', 'English', 'Grammar', 'Choose the correct form: ''Neither of the candidates ___ suitable.''', 'are', 'is', 'were', 'have been', 'B', 'Neither is singular, so it takes a singular verb: neither of the candidates is suitable.', 'medium'),
  ('de7a5641-0983-51ca-9d6a-f6f85c03e483', 'English', 'Vocabulary', 'Pick the antonym of ''AMICABLE''.', 'Friendly', 'Hostile', 'Pleasant', 'Cordial', 'B', 'Amicable means friendly and peaceable; the opposite is hostile.', 'easy'),
  ('cc8b3a1c-c726-5e95-a243-928921cd46af', 'English', 'Grammar', 'The committee ___ divided on the issue of funding. (Choose the correct verb)', 'is', 'are', 'was being', 'were being', 'A', 'A collective noun like committee is treated as a single unit here, so a singular verb is correct: the committee is divided.', 'medium'),
  ('858f5a62-66ca-5bf8-81d1-7196c854828a', 'English', 'Spelling', 'Pick the correctly spelled word.', 'Occurrence', 'Occurence', 'Occourence', 'Occurence', 'A', 'Occurrence keeps the double r and adds -ence: the correct spelling is occurrence.', 'medium'),
  ('3093159e-7963-5cba-bae9-9c7abca1dfa9', 'English', 'Grammar', 'Which sentence is grammatically correct?', 'She don''t like coffee.', 'He go to school every day.', 'They have finished their homework.', 'I am agree with you.', 'C', 'Only C uses proper subject-verb agreement and tense; the others contain agreement or form errors.', 'easy'),
  ('703d23f6-b7e8-5946-ba90-5957886f64ab', 'English', 'Vocabulary', 'Pick the word closest in meaning to ''UBIQUITOUS''.', 'Rare', 'Everywhere-present', 'Hidden', 'Absent', 'B', 'Ubiquitous means present everywhere at once; rare, hidden, and absent are opposites.', 'hard'),
  ('5dee80c0-15ff-5d60-b470-0b0b084709f1', 'English', 'Sentence Completion', 'Complete: ''By the time we arrived, the show ___ already begun.''', 'has', 'had', 'have', 'will have', 'B', 'By the time we arrived (past) refers to an action completed before it, so the past perfect had is correct.', 'medium'),
  ('3160bfba-92a9-5da6-9638-bed9be6ed7ac', 'English', 'Vocabulary', 'Pick the antonym of ''TRANSIENT''.', 'Temporary', 'Permanent', 'Fleeting', 'Brief', 'B', 'Transient means lasting only a short time; the opposite is permanent.', 'medium'),
  ('785e42dd-4aa6-5398-a24c-0d2765e6a517', 'English', 'Comprehension', 'Urban areas are usually several degrees warmer than the surrounding countryside, a pattern called the heat-island effect, driven by concrete, asphalt, and the waste heat of buildings and vehicles. What is the main cause of the heat-island effect?', 'Increased rainfall', 'Surfaces and waste heat such as concrete, asphalt, and traffic', 'Natural green spaces', 'Cool ocean breezes', 'B', 'The passage states heat islands come from concrete, asphalt, and waste heat of buildings and vehicles.', 'medium'),
  ('8d462bb0-95c7-55f7-8325-c348421dde4a', 'English', 'Grammar', 'Choose the correct form: ''One of my friends ___ in Karachi.''', 'live', 'lives', 'living', 'have lived', 'B', 'One of + plural noun still takes a singular verb: one of my friends lives in Karachi.', 'easy'),
  ('e2c9bf53-69a9-5573-800d-61aab696dc0a', 'English', 'Sentence Completion', 'Pick the best word for the blank: ''The professor''s lecture was so ___ that even the sleepy students stayed awake.''', 'monotonous', 'engaging', 'tedious', 'boring', 'B', 'An engaging lecture holds attention; monotonous, tedious, and boring would make students drowsier.', 'hard')
)
insert into public.questions
  (question_key, subject, topic, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, source, status)
select i.question_key, i.subject, i.topic, i.question_text, i.option_a, i.option_b, i.option_c, i.option_d, i.correct_answer, i.explanation, i.difficulty,
  'imported', 'published'
from incoming i
on conflict (question_key) where question_key is not null do update set
  subject = excluded.subject,
  topic = excluded.topic,
  question_text = excluded.question_text,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_answer = excluded.correct_answer,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  updated_at = now()
;

-- Result summary (shows in the editor output):
select subject, count(*) as questions
from public.questions
where status = 'published'
group by subject order by questions desc;
